CREATE OR REPLACE FUNCTION private.aqari_audit_contract_versions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;previous jsonb;actor text;d jsonb:=private.aqari_unwrap(new.payload);old_d jsonb:=private.aqari_unwrap(old.payload);
begin
 select display_name into actor from public.aqari_profiles where user_id=auth.uid();
 for c in select value from jsonb_array_elements(coalesce(d->'contractsV202','[]')) loop
  select x into previous from jsonb_array_elements(coalesce(old_d->'contractsV202','[]')) x where x->>'id'=c->>'id';
  if c=previous or c->>'source' is distinct from 'v267-cloud' then continue;end if;
  insert into private.aqari_contract_versions(workspace_id,contract_ref,actor_id,actor_name,reason,before_snapshot,after_snapshot) values(new.workspace_id,c->>'id',auth.uid(),coalesce(actor,auth.uid()::text),coalesce(nullif(c->>'changeReason',''),'إنشاء أو انتقال حالة عقد'),previous,c);
 end loop;return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_can(w uuid, s text, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text;cfg jsonb;v jsonb;allowed boolean;
begin
 if auth.uid() is null or a not in ('read','write') then return false;end if;
 select role::text into r from public.aqari_memberships where workspace_id=w and user_id=auth.uid() and is_active;
 if r is null then return false;end if;
 if s='administration' then return r='general_manager';end if;
 if not(s=any(private.aqari_section_keys())) then return false;end if;
 select settings into cfg from public.aqari_workspace_controls where workspace_id=w;
 if r='general_manager' and a='read' then return true;end if;
 if coalesce((cfg#>>array['sections',s])::boolean,true)=false then return false;end if;
 if r='general_manager' then return true;end if;
 if a='read' and s='contracts' and (not private.aqari_can(w,'tenants','read') or not private.aqari_can(w,'properties','read')) then return false;end if;
 if a='read' and s='collections' and not private.aqari_can(w,'contracts','read') then return false;end if;
 allowed:=case when a='read' then s not in ('partners','employees') or (r='accountant' and s='employees')
   when r='property_manager' then s in ('properties','tenants','contracts','maintenance','documents')
   when r='accountant' then s in ('collections','finance','employees','notifications') else false end;
 v:=cfg#>array['permissions','role:'||r,s,a];if v is not null then allowed:=(v#>>'{}')::boolean;end if;
 v:=cfg#>array['permissions','user:'||auth.uid()::text,s,a];if v is not null then allowed:=(v#>>'{}')::boolean;end if;
 -- Existing immutable role ceilings still apply; a viewer cannot become a writer here.
 if a='write' and (r='viewer' or (r='accountant' and s in ('properties','tenants','contracts','partners'))) then return false;end if;
 return allowed and (a='read' or private.aqari_can(w,s,'read'));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_contract_due(c jsonb, period text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare a jsonb;amount numeric:=(c->>'rent')::numeric;
begin
 if c->>'rentalTermsVersion'='1' then
  if c->>'freeMonthApproved'='true' and c->>'freeMonthPeriod'=period then return 0;end if;
  for a in select value from jsonb_array_elements(coalesce(c->'rentAdjustments','[]')) loop
   if a->>'effectiveMonth'<=period then amount:=(a->>'rent')::numeric;end if;
  end loop;
 end if;return amount;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_document_entity(w uuid, t text, r text, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if t='property' then return private.aqari_can(w,'properties',a) and exists(select 1 from public.aqari_properties where workspace_id=w and external_ref=r);
 elsif t='tenant' then return private.aqari_can(w,'tenants',a) and exists(select 1 from public.aqari_tenants where workspace_id=w and external_ref=r);
 elsif t='lease' then return private.aqari_can(w,'contracts',a) and exists(select 1 from public.aqari_leases where workspace_id=w and external_ref=r);
 else return false;end if;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_document_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved storage.objects%rowtype;
begin
 if not private.aqari_can(new.workspace_id,'documents','write') or not private.aqari_document_entity(new.workspace_id,new.entity_type,new.entity_ref,'write') then raise exception 'DOCUMENT_ENTITY_NOT_FOUND' using errcode='42501';end if;
 if new.created_by is distinct from auth.uid() then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if tg_op='INSERT' then
  if new.status<>'draft' or new.size_bytes is not null or new.uploaded_at is not null then raise exception 'INVALID_DOCUMENT';end if;
  if new.storage_path not like new.workspace_id::text||'/'||new.id::text||'.%' then raise exception 'INVALID_DOCUMENT_PATH';end if;
  new.created_at:=now();
 else
  if old.status<>'draft' or old.created_by is distinct from auth.uid() then raise exception 'DOCUMENT_IMMUTABLE' using errcode='42501';end if;
  if (to_jsonb(new)-array['status','size_bytes','checksum_sha256','uploaded_at']) is distinct from (to_jsonb(old)-array['status','size_bytes','checksum_sha256','uploaded_at']) then raise exception 'DOCUMENT_IMMUTABLE';end if;
  if new.status not in ('uploaded','cancelled') then raise exception 'INVALID_DOCUMENT';end if;
  if new.status='uploaded' then
   select * into saved from storage.objects where bucket_id=new.storage_bucket and name=new.storage_path;
   if not found or coalesce((saved.metadata->>'size')::bigint,0)<>new.size_bytes or new.size_bytes not between 1 and 26214400 or saved.metadata->>'mimetype' is distinct from new.mime_type then raise exception 'STORED_FILE_NOT_CONFIRMED';end if;
   new.uploaded_at:=now();
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_guard_section_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_data jsonb;new_data jsonb;k text;
begin
 new_data:=private.aqari_unwrap(new.payload);old_data:=case when tg_op='INSERT' then '{}'::jsonb else private.aqari_unwrap(old.payload) end;
 for k in select jsonb_object_keys(coalesce(old_data,'{}')||coalesce(new_data,'{}')) loop
  if old_data->k is distinct from new_data->k and not private.aqari_can(new.workspace_id,private.aqari_state_section(k),'write') then raise exception 'SECTION_WRITE_DENIED:%',k using errcode='42501';end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allowed private.aqari_allowed_users%rowtype;w uuid;t public.aqari_tenants%rowtype;partner_name text;
begin
 select a.display_name into partner_name from private.aqari_partner_access a where a.email=lower(btrim(coalesce(new.email,''))) and a.is_active order by a.updated_at desc limit 1;
 if partner_name is not null then
  if exists(select 1 from private.aqari_allowed_users where email=lower(new.email) and is_active) then raise exception 'PARTNER_STAFF_CONFLICT';end if;
  insert into public.aqari_profiles(user_id,display_name) values(new.id,partner_name);
  update private.aqari_partner_access set user_id=new.id where email=lower(new.email);
  return new;
 end if;
 select * into allowed from private.aqari_allowed_users where email=lower(btrim(coalesce(new.email,''))) and is_active;
 if found then
  select id into w from public.aqari_workspaces where slug=allowed.workspace_slug;
  if w is null then raise exception 'WORKSPACE_NOT_CONFIGURED';end if;
  insert into public.aqari_profiles(user_id,display_name) values(new.id,allowed.display_name);
  insert into public.aqari_memberships(workspace_id,user_id,role,is_active) values(w,new.id,allowed.role,true);
 else
  if (select count(*) from public.aqari_tenants where lower(email)=lower(new.email) and is_active)<>1 then raise exception 'EMAIL_NOT_AUTHORIZED' using errcode='28000';end if;
  select * into t from public.aqari_tenants where lower(email)=lower(new.email) and is_active;
  insert into public.aqari_profiles(user_id,display_name) values(new.id,t.full_name);
  insert into public.aqari_portal_accounts(user_id,workspace_id,tenant_id) values(new.id,t.workspace_id,t.id);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb:=to_jsonb(new); b jsonb; actor text;
begin
 if tg_op='UPDATE' then b:=to_jsonb(old);end if;
 if auth.uid() is null then actor:='النظام — تجهيز الرواتب';else select display_name into actor from public.aqari_profiles where user_id=auth.uid();end if;
 insert into private.aqari_hr_audit(workspace_id,employee_id,entity,entity_id,actor_id,actor_name,operation,before_value,after_value)
 values((v->>'workspace_id')::uuid,case when tg_table_name='aqari_hr_employees' then (v->>'id')::uuid else (v->>'employee_id')::uuid end,
 tg_table_name,coalesce(v->>'id',v->>'user_id'),auth.uid(),coalesce(actor,auth.uid()::text),tg_op,b,v);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_prepare(w uuid, period date, employee uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
 if period<>date_trunc('month',period)::date then raise exception 'شهر غير صالح.';end if;
 insert into private.aqari_hr_payroll(workspace_id,employee_id,month,snapshot,basic,allowances)
 select w,e.id,period,e.profile||jsonb_build_object('hired_on',e.hired_on,'property_ids',e.property_ids,'properties',(select jsonb_agg(p.name order by p.name) from public.aqari_properties p where p.workspace_id=w and p.id=any(e.property_ids))),e.basic,e.allowances
 from private.aqari_hr_employees e where e.workspace_id=w and e.status in ('active','leave') and e.hired_on<(period+interval '1 month')::date and (employee is null or e.id=employee)
 on conflict(employee_id,month) do nothing;
 get diagnostics n=row_count;return n;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_slip_details(v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text;
begin
 if jsonb_typeof(v) is distinct from 'object' or coalesce(v->>'template','') not in ('standard','dhahawi-v1') or exists(select 1 from jsonb_object_keys(v) x where x not in ('template','payer_ar','payer_en')) then raise exception 'نموذج سند غير صالح.';end if;
 foreach k in array array['payer_ar','payer_en'] loop
  if v ? k and (jsonb_typeof(v->k) is distinct from 'string' or length(v->>k)>200 or (v->>k) ~ '[<>[:cntrl:]]') then raise exception 'اسم مسؤول صرف غير صالح.';end if;
 end loop;
 return v;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_imported_tenant_read(w uuid, ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tenant public.aqari_tenants; revision bigint; history jsonb;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'tenants','read') then raise exception 'غير مصرح بعرض الملف.' using errcode='42501';end if;
 select * into tenant from public.aqari_tenants where workspace_id=w and external_ref=ref and import_source is not null;
 if not found then raise exception 'الملف المستورد غير موجود.';end if;
 select s.revision into revision from public.aqari_app_state s where s.workspace_id=w;
 select coalesce(jsonb_agg(row_to_json(h) order by h.id desc),'[]'::jsonb) into history from
 (select id,reason,created_at,before_profile,after_profile from private.aqari_imported_tenant_edits where workspace_id=w and tenant_id=tenant.id order by id desc limit 10) h;
 return jsonb_build_object('profile',tenant.profile,'revision',revision,'history',history);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_imported_tenant_save(w uuid, ref text, patch jsonb, expected bigint, reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tenant public.aqari_tenants; state public.aqari_app_state; d jsonb; next_profile jsonb; f text; val text; display_name text;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'tenants','write') then raise exception 'غير مصرح بتعديل الملف.' using errcode='42501';end if;
 if expected is null or reason is null or length(btrim(reason)) not between 3 and 500 or jsonb_typeof(patch) is distinct from 'object' then raise exception 'أدخل سبب التعديل وراجع البيانات.';end if;
 if exists(select 1 from jsonb_object_keys(patch) k where k not in ('nameAr','nameEn','civilId','passportNo','phone','email','nationality','address')) then raise exception 'لا يمكن تغيير بيانات المصدر أو الربط.';end if;
 select * into state from public.aqari_app_state where workspace_id=w for update;
 if not found or state.revision<>expected then raise exception 'تغيّرت البيانات؛ حدّث الملف قبل الحفظ.' using errcode='40001';end if;
 select * into tenant from public.aqari_tenants where workspace_id=w and external_ref=ref and import_source is not null for update;
 if not found then raise exception 'الملف المستورد غير موجود.';end if;
 d:=private.aqari_unwrap(state.payload);
 if not exists(select 1 from jsonb_array_elements(coalesce(d->'tenantProfilesV267','[]')) x where x->>'id'=ref and x=tenant.profile) then raise exception 'تعارض بين الملف والسجل المحفوظ؛ يلزم المراجعة.';end if;
 next_profile:=tenant.profile;
 for f,val in select key,value from jsonb_each_text(patch) loop
  if jsonb_typeof(patch->f) is distinct from 'string' or length(val)>300 then raise exception 'راجع نوع البيانات وطولها.';end if;
  val:=btrim(val);
  if f in ('civilId','phone') then val:=translate(val,'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789');end if;
  if f='phone' then val:=regexp_replace(val,'[ ()-]','','g');end if;
  next_profile:=jsonb_set(next_profile,array[f],to_jsonb(val));
 end loop;
 display_name:=coalesce(nullif(next_profile->>'nameAr',''),nullif(next_profile->>'nameEn',''));
 if display_name is null then raise exception 'أدخل اسم المستأجر بالعربية أو الإنجليزية.';end if;
 if coalesce(next_profile->>'civilId','')<>'' and next_profile->>'civilId' !~ '^[0-9]{12}$' then raise exception 'الرقم المدني يجب أن يكون ١٢ رقماً أو يُترك فارغاً.';end if;
 if coalesce(next_profile->>'phone','')<>'' and next_profile->>'phone' !~ '^[+]?[0-9]{8,15}$' then raise exception 'راجع رقم الهاتف أو اتركه فارغاً.';end if;
 if coalesce(next_profile->>'email','')<>'' and next_profile->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'راجع البريد الإلكتروني.';end if;
 if coalesce(next_profile->>'civilId','')<>'' and exists(select 1 from public.aqari_tenants t where t.workspace_id=w and t.id<>tenant.id and t.civil_id=next_profile->>'civilId') then raise exception 'الرقم المدني مرتبط بمستأجر آخر.';end if;
 -- Email is the portal identity; do not silently transfer an existing account.
 if coalesce(tenant.profile->>'email','') is distinct from coalesce(next_profile->>'email','') then
  if exists(select 1 from auth.users u where lower(u.email)=lower(tenant.profile->>'email') or lower(u.email)=lower(next_profile->>'email')) then raise exception 'البريد مرتبط بحساب؛ يلزم إجراء مستقل للتحقق من هوية صاحب الحساب.';end if;
 end if;
 update public.aqari_tenants set full_name=display_name,civil_id=nullif(next_profile->>'civilId',''),phone=nullif(next_profile->>'phone',''),email=nullif(lower(next_profile->>'email'),''),profile=next_profile where id=tenant.id and workspace_id=w;
 d:=jsonb_set(d,'{tenantProfilesV267}',(select jsonb_agg(case when x->>'id'=ref then next_profile else x end order by n) from jsonb_array_elements(d->'tenantProfilesV267') with ordinality a(x,n)));
 d:=jsonb_set(d,'{tenants}',coalesce((select jsonb_agg(case when x->>4=ref or exists(select 1 from jsonb_array_elements(x) v where v->>'aqariTenantProfileV267'=ref) then jsonb_set(x,'{0}',to_jsonb(display_name)) else x end order by n) from jsonb_array_elements(coalesce(d->'tenants','[]')) with ordinality a(x,n)),'[]'));
 d:=jsonb_set(d,'{tenantDirectoryV202}',coalesce((select jsonb_agg(case when x->>'tenantProfileId'=ref then x||jsonb_build_object('tenant',display_name,'nameAr',next_profile->>'nameAr','nameEn',next_profile->>'nameEn','passportNo',next_profile->>'passportNo','phone',next_profile->>'phone','email',next_profile->>'email','civilId',next_profile->>'civilId','nationality',next_profile->>'nationality') else x end order by n) from jsonb_array_elements(coalesce(d->'tenantDirectoryV202','[]')) with ordinality a(x,n)),'[]'));
 d:=jsonb_set(d,'{tenantPreparationDraftsV267}',coalesce((select jsonb_agg(x) from jsonb_array_elements(coalesce(d->'tenantPreparationDraftsV267','[]')) x where x->>'id'<>ref),'[]'));
 -- Contract snapshots, original source statements, receipts and payment records stay historical.
 insert into private.aqari_imported_tenant_edits(workspace_id,tenant_id,actor_id,reason,before_profile,after_profile) values(w,tenant.id,auth.uid(),btrim(reason),tenant.profile,next_profile);
 update public.aqari_app_state set payload=case when state.payload->>'format'='aqari-cloud-state-v1' then jsonb_set(state.payload,'{snapshot,values,aqari_v30}',d) when state.payload->>'schema'='aqari-local-snapshot-v1' then jsonb_set(state.payload,'{values,aqari_v30}',d) else d end,revision=state.revision+1,updated_by=auth.uid(),updated_at=now() where workspace_id=w;
 return private.aqari_imported_tenant_read(w,ref);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_manage_partner_access(w uuid, email_address text, property uuid, partner_name text, enabled boolean, expected bigint, reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_email text:=lower(btrim(email_address)); target_user uuid; old_row private.aqari_partner_access%rowtype; saved private.aqari_partner_access%rowtype;
begin
 if auth.uid() is null or not private.aqari_manager(w) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if target_email is null or target_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or length(target_email)>254
 or partner_name is null or length(btrim(partner_name)) not between 1 and 120 or enabled is null
 or reason is null or length(btrim(reason)) not between 3 and 500 or expected is null or expected<0 then raise exception 'INVALID_PARTNER_ACCESS';end if;
 perform 1 from public.aqari_workspaces where id=w for update;
 if not exists(select 1 from public.aqari_properties p where p.id=property and p.workspace_id=w) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select id into target_user from auth.users where lower(email)=target_email for update;
 if exists(select 1 from public.aqari_memberships m where m.user_id=target_user and m.workspace_id=w)
 or exists(select 1 from private.aqari_allowed_users a join public.aqari_workspaces x on x.slug=a.workspace_slug where a.email=target_email and x.id=w) then
  raise exception 'PARTNER_STAFF_CONFLICT' using errcode='42501';
 end if;
 select * into old_row from private.aqari_partner_access a where a.workspace_id=w and a.email=target_email and a.property_id=property;
 if coalesce(old_row.revision,0) is distinct from expected then raise exception 'REVISION_CONFLICT' using errcode='40001';end if;
 insert into private.aqari_partner_access(workspace_id,email,property_id,user_id,display_name,is_active,revision,updated_by)
 values(w,target_email,property,target_user,btrim(partner_name),enabled,coalesce(old_row.revision,0)+1,auth.uid())
 on conflict(workspace_id,email,property_id) do update set user_id=excluded.user_id,display_name=excluded.display_name,is_active=excluded.is_active,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=now()
 returning * into saved;
 insert into public.aqari_control_audit(workspace_id,actor_id,action,entity_ref,reason,before_value,after_value)
 values(w,auth.uid(),'partner.access',property::text,btrim(reason),to_jsonb(old_row),to_jsonb(saved));
 return to_jsonb(saved)-'updated_by';
end $function$

CREATE OR REPLACE FUNCTION private.aqari_partner_summary(property uuid DEFAULT NULL::uuid, month_start date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account auth.users%rowtype; result jsonb; p public.aqari_properties%rowtype; scope_id uuid;
begin
 if auth.uid() is null then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select * into account from auth.users where id=auth.uid();
 if account.email_confirmed_at is null then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if property is null then
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'workspace_id',x.workspace_id,'name',x.name) order by x.name,x.id),'[]') into result
  from public.aqari_properties x where exists(select 1 from private.aqari_partner_access a where a.property_id=x.id and a.workspace_id=x.workspace_id and a.user_id=auth.uid() and a.email=lower(account.email) and a.is_active)
  and not exists(select 1 from public.aqari_memberships m where m.user_id=auth.uid() and m.workspace_id=x.workspace_id);
  return jsonb_build_object('user_id',auth.uid(),'properties',result);
 end if;
 select a.workspace_id into scope_id from private.aqari_partner_access a where a.property_id=property and a.user_id=auth.uid() and a.email=lower(account.email) and a.is_active
 and not exists(select 1 from public.aqari_memberships m where m.user_id=auth.uid() and m.workspace_id=a.workspace_id);
 if scope_id is null then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if month_start is null or month_start<>date_trunc('month',month_start)::date or month_start not between date '2000-01-01' and date '2100-12-01' then raise exception 'INVALID_MONTH';end if;
 select * into strict p from public.aqari_properties where id=property and workspace_id=scope_id;
 return jsonb_build_object('user_id',auth.uid(),'workspace_id',scope_id,'property_id',p.id,'name',p.name,'month',month_start,
 'unit_count',(select count(*) from public.aqari_units u where u.workspace_id=scope_id and u.property_id=p.id),
 'draft_leases',(select count(*) from public.aqari_leases l join public.aqari_units u on u.id=l.unit_id and u.workspace_id=l.workspace_id where l.workspace_id=scope_id and u.property_id=p.id and l.status='draft'),
 'receipt_count',(select count(*) from public.aqari_rent_payments r join public.aqari_leases l on l.id=r.lease_id and l.workspace_id=r.workspace_id join public.aqari_units u on u.id=l.unit_id and u.workspace_id=l.workspace_id where r.workspace_id=scope_id and u.property_id=p.id and r.paid_at>=month_start and r.paid_at<(month_start+interval '1 month')::date),
 'recorded_receipts',(select coalesce(sum(r.amount),0) from public.aqari_rent_payments r join public.aqari_leases l on l.id=r.lease_id and l.workspace_id=r.workspace_id join public.aqari_units u on u.id=l.unit_id and u.workspace_id=l.workspace_id where r.workspace_id=scope_id and u.property_id=p.id and r.paid_at>=month_start and r.paid_at<(month_start+interval '1 month')::date));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_prepare_state_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := pg_catalog.now();
  new.updated_by := auth.uid();

  if tg_op = 'UPDATE' then
    new.revision := old.revision + 1;
  else
    new.revision := 1;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.aqari_review_source_lease(p_workspace_id uuid, p_lease_id uuid, p_document_id uuid, p_action text, p_deposit numeric, p_note text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.aqari_leases%rowtype; t public.aqari_tenants%rowtype; doc public.aqari_documents%rowtype;
 saved public.aqari_app_state%rowtype; d jsonb; next_snapshot jsonb; next_status text; review_id uuid; revision_after bigint;
begin
 if auth.uid() is null or not private.aqari_manager(p_workspace_id)
 or not private.aqari_can(p_workspace_id,'contracts','write') or not private.aqari_can(p_workspace_id,'documents','read')
 then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_action is null or p_action not in ('approve','sign') or p_note is null or length(btrim(p_note)) not between 10 and 2000 then raise exception 'REVIEW_DETAILS_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text,0));
 select * into strict saved from public.aqari_app_state where workspace_id=p_workspace_id for update;
 if saved.revision is distinct from p_expected_revision then raise exception 'REVISION_CONFLICT' using errcode='40001';end if;
 select * into strict l from public.aqari_leases where workspace_id=p_workspace_id and id=p_lease_id for update;
 if l.import_source is null then raise exception 'SOURCE_LEASE_REQUIRED';end if;
 if (p_action='approve' and l.status<>'draft') or (p_action='sign' and l.status<>'approved') then raise exception 'INVALID_REVIEW_TRANSITION';end if;
 select * into strict t from public.aqari_tenants where workspace_id=p_workspace_id and id=l.tenant_id;
 if nullif(btrim(t.full_name),'') is null or l.start_date is null or l.end_date is null or l.end_date<l.start_date
 or jsonb_array_length(coalesce(l.snapshot->'pending','[]'))>0 then raise exception 'SOURCE_FIELDS_PENDING';end if;
 if p_deposit is null or p_deposit<0 or p_deposit>999999999999.999 or p_deposit<>round(p_deposit,3) then raise exception 'DOCUMENTED_DEPOSIT_REQUIRED';end if;
 select * into strict doc from public.aqari_documents where workspace_id=p_workspace_id and id=p_document_id;
 if doc.status<>'uploaded' or doc.document_type<>'signed_contract' or doc.entity_type<>'lease' or doc.entity_ref<>l.external_ref
 or doc.checksum_sha256 is null or doc.size_bytes<=0 or not exists(select 1 from storage.objects where bucket_id=doc.storage_bucket and name=doc.storage_path)
 then raise exception 'VERIFIED_LEASE_DOCUMENT_REQUIRED';end if;
 if p_action='sign' and (p_deposit is distinct from l.deposit or not exists(select 1 from public.aqari_source_lease_reviews where workspace_id=p_workspace_id and lease_id=p_lease_id and action='approve' and document_id=p_document_id)) then raise exception 'APPROVED_DOCUMENT_REQUIRED';end if;
 next_status:=case p_action when 'approve' then 'approved' else 'signed' end;
 review_id:=gen_random_uuid();
 next_snapshot:=l.snapshot||jsonb_build_object('status',next_status,'deposit',p_deposit,'tenant',t.full_name,'tenantProfile',t.profile,
 'importStatus','reviewed','operationalReview',jsonb_build_object('id',review_id,'documentId',doc.id,'documentSha256',doc.checksum_sha256,'reviewedBy',auth.uid(),'reviewedAt',now(),'note',btrim(p_note),'action',p_action));
 -- Imported sourceValues/sourceReference remain intact; the dedicated audit retains before and after.
 update public.aqari_leases set status=next_status,deposit=p_deposit,snapshot=next_snapshot where workspace_id=p_workspace_id and id=p_lease_id;
 d:=private.aqari_unwrap(saved.payload);
 if (select count(*) from jsonb_array_elements(d->'contractsV202') x where x->>'id'=l.external_ref)<>1 then raise exception 'SOURCE_STATE_LINK_REQUIRED';end if;
 d:=jsonb_set(d,'{contractsV202}',(select jsonb_agg(case when value->>'id'=l.external_ref then next_snapshot else value end order by ordinality) from jsonb_array_elements(d->'contractsV202') with ordinality));
 -- Same locked transaction: projection verifies the reviewed snapshot against the lease row.
 update public.aqari_app_state set payload=d where workspace_id=p_workspace_id;
 select revision into revision_after from public.aqari_app_state where workspace_id=p_workspace_id;
 insert into public.aqari_source_lease_reviews(id,workspace_id,lease_id,document_id,action,reviewer_id,note,before_snapshot,after_snapshot)
 values(review_id,p_workspace_id,p_lease_id,p_document_id,p_action,auth.uid(),btrim(p_note),l.snapshot,next_snapshot);
 insert into public.aqari_operation_audit(workspace_id,user_id,action,revision) values(p_workspace_id,auth.uid(),'source_lease_'||p_action||':'||review_id::text,revision_after);
 return jsonb_build_object('lease_id',p_lease_id,'status',next_status,'review_id',review_id,'revision',revision_after);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := pg_catalog.now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.aqari_v267_maintenance_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 if tg_op='UPDATE' then
  if not private.aqari_writer(new.workspace_id) then raise exception 'WRITE_DENIED' using errcode='42501';end if;
  if new.status=old.status and new.cost=old.cost then return old;end if;
  if old.status in ('completed','cancelled') then raise exception 'MAINTENANCE_CLOSED';end if;
  if new.status<>old.status and not (
   old.status='received' and new.status in ('assigned','in_progress','cancelled') or
   old.status='assigned' and new.status in ('in_progress','cancelled') or
   old.status='in_progress' and new.status in ('completed','cancelled')) then raise exception 'INVALID_MAINTENANCE_TRANSITION';end if;
  new.revision:=old.revision+1;new.updated_at:=now();
 end if;
 insert into public.aqari_operation_audit(workspace_id,user_id,action,revision) values(new.workspace_id,auth.uid(),jsonb_build_object('operation','maintenance_'||lower(tg_op),'request_id',new.id,'status',new.status,'cost',new.cost,'previous_status',case when tg_op='UPDATE' then old.status else null end,'previous_cost',case when tg_op='UPDATE' then old.cost else null end)::text,new.revision);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_v267_prepare_reminders(w uuid, as_of date, grace_day integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare period_start date;window_start date;window_end date;inserted integer;
begin
 if auth.uid() is null or not private.aqari_can(w,'notifications','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if grace_day is null or grace_day<1 or grace_day>27 or as_of is null then raise exception 'INVALID_REMINDER_WINDOW';end if;
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise exception 'WORKSPACE_REQUIRED';end if;
 perform private.aqari_reconcile_reminder_queue(w);
 period_start:=date_trunc('month',as_of)::date;
 if extract(day from as_of)>=28 then period_start:=(period_start+interval '1 month')::date;end if;
 window_start:=(period_start-interval '1 month')::date+27;
 window_end:=period_start+grace_day-1;
 if as_of<window_start or as_of>window_end or (as_of-window_start)%2<>0 then return 0;end if;
 insert into public.aqari_notification_outbox(workspace_id,lease_id,period,kind,channel,status,scheduled_at,idempotency_key)
 select w,l.id,period_start,'rent_reminder',ch.channel,'awaiting_configuration',(as_of::timestamp at time zone 'Asia/Kuwait'),'reminder:'||l.id::text||':'||period_start::text||':'||as_of::text||':'||ch.channel
 from public.aqari_leases l join public.aqari_tenants t on t.id=l.tenant_id and t.workspace_id=w
 cross join (values('email'::text),('whatsapp'::text)) ch(channel)
 where l.workspace_id=w and l.status='signed' and t.is_active and l.start_date<=(period_start+interval '1 month - 1 day')::date and l.end_date>=period_start
 and ((ch.channel='email' and nullif(btrim(t.email),'') is not null) or (ch.channel='whatsapp' and nullif(btrim(t.phone),'') is not null))
 and private.aqari_reminder_due(l.snapshot,l.monthly_rent,period_start)>coalesce((select sum(p.amount) from public.aqari_rent_payments p where p.workspace_id=w and p.lease_id=l.id and p.period=period_start),0)
 on conflict(workspace_id,idempotency_key) do nothing;
 get diagnostics inserted=row_count;return inserted;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_v267_project_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb;old_d jsonb;r jsonb;v_contract jsonb;v_profile jsonb;row_data jsonb;receipt_data jsonb;role_name text;prop_id uuid;tenant_ref uuid;unit_ref uuid;lease_ref uuid;payment_ref uuid;rent_value numeric;paid_sum numeric;key_name text;source_ref text;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 select role::text into role_name from public.aqari_memberships where workspace_id=new.workspace_id and user_id=auth.uid() and is_active;
 if role_name is null or role_name not in ('general_manager','property_manager','accountant') then raise exception 'WRITE_DENIED' using errcode='42501';end if;
 d:=case when new.payload->>'format'='aqari-cloud-state-v1' then new.payload#>'{snapshot,values,aqari_v30}' when new.payload->>'schema'='aqari-local-snapshot-v1' then new.payload#>'{values,aqari_v30}' else new.payload end;
 old_d:=case when old.payload->>'format'='aqari-cloud-state-v1' then old.payload#>'{snapshot,values,aqari_v30}' when old.payload->>'schema'='aqari-local-snapshot-v1' then old.payload#>'{values,aqari_v30}' else old.payload end;
 if jsonb_typeof(d)<>'object' then raise exception 'INVALID_STATE';end if;
 foreach key_name in array array['properties','tenantProfilesV267','contractsV202','rentLedgerV202','collections','rentReceiptsV267'] loop
  if jsonb_typeof(coalesce(d->key_name,'[]'))<>'array' then raise exception 'INVALID_ARRAY:%',key_name;end if;
  if role_name='accountant' and key_name in ('properties','tenantProfilesV267','contractsV202') and coalesce(d->key_name,'[]')<>coalesce(old_d->key_name,'[]') then raise exception 'ACCOUNTANT_RESTRICTED' using errcode='42501';end if;
 end loop;
 -- Sensitive historical records remain present; use dedicated cancellation workflows later.
 if exists(select 1 from public.aqari_tenants t where t.workspace_id=new.workspace_id and not exists(select 1 from jsonb_array_elements(coalesce(d->'tenantProfilesV267','[]')) profile_item where profile_item->>'id'=t.external_ref)) then raise exception 'TENANT_HISTORY_REQUIRED';end if;
 if exists(select 1 from public.aqari_leases l where l.workspace_id=new.workspace_id and not exists(select 1 from jsonb_array_elements(coalesce(d->'contractsV202','[]')) contract_item where contract_item->>'id'=l.external_ref)) then raise exception 'LEASE_HISTORY_REQUIRED';end if;
 for r in select value from jsonb_array_elements(coalesce(d->'properties','[]')) loop
  if jsonb_typeof(r)<>'array' or nullif(btrim(r->>0),'') is null then raise exception 'INVALID_PROPERTY';end if;
  prop_id:=md5(new.workspace_id::text||':property:'||btrim(r->>0))::uuid;
  insert into public.aqari_properties values(prop_id,new.workspace_id,btrim(r->>0),btrim(r->>0),r) on conflict(id) do update set metadata=excluded.metadata;
 end loop;
 for v_profile in select value from jsonb_array_elements(coalesce(d->'tenantProfilesV267','[]')) loop
  if exists(select 1 from public.aqari_tenants t where t.workspace_id=new.workspace_id and t.external_ref=v_profile->>'id' and t.import_source is not null) then
   if not exists(select 1 from public.aqari_tenants t where t.workspace_id=new.workspace_id and t.external_ref=v_profile->>'id' and t.profile=v_profile) then raise exception 'SOURCE_PROFILE_REVIEW_REQUIRED';end if;
   continue;
  end if;
  if nullif(v_profile->>'id','') is null or nullif(v_profile->>'nameAr','') is null or nullif(v_profile->>'nameEn','') is null or nullif(v_profile->>'nationality','') is null or coalesce(v_profile->>'phone','') !~ '^[+]?[0-9]{8,15}$' then raise exception 'INVALID_PROFILE';end if;
  tenant_ref:=md5(new.workspace_id::text||':tenant:'||(v_profile->>'id'))::uuid;
  insert into public.aqari_tenants(id,workspace_id,external_ref,full_name,civil_id,phone,email,profile) values(tenant_ref,new.workspace_id,v_profile->>'id',v_profile->>'nameAr',v_profile->>'civilId',v_profile->>'phone',nullif(lower(btrim(v_profile->>'email')),''),v_profile) on conflict(id) do update set full_name=excluded.full_name,civil_id=excluded.civil_id,phone=excluded.phone,email=excluded.email,profile=excluded.profile;
 end loop;
 for v_contract in select value from jsonb_array_elements(coalesce(d->'contractsV202','[]')) loop
  if exists(select 1 from public.aqari_leases l where l.workspace_id=new.workspace_id and l.external_ref=v_contract->>'id' and l.import_source is not null) then
   if not exists(select 1 from public.aqari_leases l where l.workspace_id=new.workspace_id and l.external_ref=v_contract->>'id' and l.snapshot=v_contract) then raise exception 'SOURCE_CONTRACT_REVIEW_REQUIRED';end if;
   continue;
  end if;
  if v_contract->>'source' is distinct from 'v267-cloud' then raise exception 'IMPORTED_CONTRACT_REVIEW_REQUIRED';end if;
  select id into prop_id from public.aqari_properties where workspace_id=new.workspace_id and name=v_contract->>'property';
  select id into tenant_ref from public.aqari_tenants where workspace_id=new.workspace_id and external_ref=v_contract->>'tenantId' and full_name=v_contract->>'tenant';
  if prop_id is null or tenant_ref is null or nullif(v_contract->>'unit','') is null or nullif(v_contract->>'id','') is null then raise exception 'CONTRACT_LINK_REQUIRED';end if;
  unit_ref:=md5(prop_id::text||':unit:'||translate(v_contract->>'unit','٠١٢٣٤٥٦٧٨٩','0123456789'))::uuid;
  insert into public.aqari_units values(unit_ref,new.workspace_id,prop_id,translate(v_contract->>'unit','٠١٢٣٤٥٦٧٨٩','0123456789')) on conflict(id) do nothing;
  lease_ref:=md5(new.workspace_id::text||':lease:'||(v_contract->>'id'))::uuid;
  if exists(select 1 from public.aqari_leases l where l.id=lease_ref and (l.tenant_id<>tenant_ref or l.unit_id<>unit_ref or l.contract_no<>v_contract->>'contract_no')) then raise exception 'LEASE_LINK_IMMUTABLE';end if;
  insert into public.aqari_leases(id,workspace_id,external_ref,tenant_id,unit_id,contract_no,start_date,end_date,monthly_rent,deposit,status,snapshot) values(lease_ref,new.workspace_id,v_contract->>'id',tenant_ref,unit_ref,v_contract->>'contract_no',(v_contract->>'start_date')::date,(v_contract->>'end_date')::date,(v_contract->>'rent')::numeric,coalesce((v_contract->>'deposit')::numeric,0),v_contract->>'status',v_contract) on conflict(id) do update set start_date=excluded.start_date,end_date=excluded.end_date,monthly_rent=excluded.monthly_rent,deposit=excluded.deposit,status=excluded.status,snapshot=excluded.snapshot;
 end loop;
 -- Missing/changed payment or receipt is forbidden, including direct JSON-state writers.
 for r in select * from jsonb_array_elements(coalesce(old_d->'rentLedgerV202','[]')) loop
  if not exists(select 1 from jsonb_array_elements(coalesce(d->'rentLedgerV202','[]')) p where p=r) then raise exception 'PAYMENT_IMMUTABLE';end if;
 end loop;
 for r in select * from jsonb_array_elements(coalesce(old_d->'rentReceiptsV267','[]')) loop
  if not exists(select 1 from jsonb_array_elements(coalesce(d->'rentReceiptsV267','[]')) p where p=r) then raise exception 'RECEIPT_IMMUTABLE';end if;
 end loop;
 for r in select value from jsonb_array_elements(coalesce(d->'rentLedgerV202','[]')) loop
  source_ref:=nullif(r->>'receiptNo','');
  if source_ref is null or (r->>'paid')::numeric<=0 or (r->>'paid')::numeric<>round((r->>'paid')::numeric,3) then raise exception 'INVALID_PAYMENT';end if;
  if r->>'status' not in ('مدفوع','جزئي','paid','partial') then raise exception 'UNCONFIRMED_PAYMENT';end if;
  if exists(select 1 from public.aqari_rent_payments where workspace_id=new.workspace_id and reference=source_ref) then
   if (select count(*) from jsonb_array_elements(coalesce(d->'collections','[]')) x where x->>0=source_ref)<>1 or not exists(select 1 from public.aqari_rent_payments saved where saved.workspace_id=new.workspace_id and saved.reference=source_ref and saved.record=r and exists(select 1 from jsonb_array_elements(d->'collections') x where x=saved.receipt->'record')) then raise exception 'SAVED_PAYMENT_CHANGED';end if;
   continue;
  end if;
  select l.id,l.monthly_rent into lease_ref,rent_value from public.aqari_leases l join public.aqari_tenants t on t.id=l.tenant_id join public.aqari_units u on u.id=l.unit_id join public.aqari_properties p on p.id=u.property_id where l.workspace_id=new.workspace_id and l.external_ref=r->>'contractId' and l.contract_no=r->>'contractNo' and t.full_name=r->>'tenant' and u.unit_no=r->>'unit' and p.name=r->>'property' and l.status='signed' and to_char(l.start_date,'YYYY-MM')<=r->>'period' and to_char(l.end_date,'YYYY-MM')>=r->>'period';
  if lease_ref is null then raise exception 'ACTIVE_SAVED_CONTRACT_REQUIRED';end if;
  if (select count(*) from jsonb_array_elements(coalesce(d->'collections','[]')) x where x->>0=source_ref)<>1 or (select count(*) from jsonb_array_elements(coalesce(d->'rentLedgerV202','[]')) x where x->>'receiptNo'=source_ref)<>1 or (select count(*) from jsonb_array_elements(coalesce(d->'rentReceiptsV267','[]')) x where x->>'id'=source_ref)<>1 then raise exception 'UNIQUE_RECEIPT_REQUIRED';end if;
  select x into row_data from jsonb_array_elements(d->'collections') x where x->>0=source_ref;
  select x into receipt_data from jsonb_array_elements(d->'rentReceiptsV267') x where x->>'id'=source_ref;
  if (row_data->>2)::numeric<>(r->>'paid')::numeric or row_data->>1<>r->>'tenant' or row_data->>4<>r->>'property' or row_data->>5<>r->>'paidAt' or row_data->>6<>r->>'unit' or row_data->>8<>r->>'period' or receipt_data->'record' is distinct from row_data or receipt_data#>>'{contract,id}' is distinct from r->>'contractId' or receipt_data->>'template' is distinct from 'rent-voucher-v267-1' then raise exception 'RECEIPT_LINK_MISMATCH';end if;
  select snapshot into v_contract from public.aqari_leases where workspace_id=new.workspace_id and id=lease_ref;
  rent_value:=private.aqari_reminder_due(v_contract,rent_value,((r->>'period')||'-01')::date);
  if jsonb_typeof(row_data) is distinct from 'array' or jsonb_array_length(row_data)<>10
   or row_data->>3 is distinct from r->>'status' or row_data->>9 is distinct from r->>'method'
   or receipt_data#>>'{contract,status}' is distinct from 'signed'
   or receipt_data#>>'{contract,contract_no}' is distinct from r->>'contractNo'
   or receipt_data#>>'{contract,tenant}' is distinct from r->>'tenant'
   or receipt_data#>>'{contract,property}' is distinct from r->>'property'
   or receipt_data#>>'{contract,unit}' is distinct from r->>'unit'
   or receipt_data#>>'{contract,start_date}' is distinct from v_contract->>'start_date'
   or receipt_data#>>'{contract,end_date}' is distinct from v_contract->>'end_date'
   then raise exception 'RECEIPT_SNAPSHOT_INVALID';end if;
  payment_ref:=md5(new.workspace_id::text||':payment:'||source_ref)::uuid;
  insert into public.aqari_rent_payments(id,workspace_id,lease_id,reference,amount,period,paid_at,status,payment_method,record,receipt) values(payment_ref,new.workspace_id,lease_ref,source_ref,(r->>'paid')::numeric,((r->>'period')||'-01')::date,(r->>'paidAt')::date,r->>'status',r->>'method',r,receipt_data) on conflict(id) do nothing;
  select coalesce(sum(amount),0) into paid_sum from public.aqari_rent_payments where workspace_id=new.workspace_id and lease_id=lease_ref and period=((r->>'period')||'-01')::date;
  if paid_sum>rent_value then raise exception 'PAYMENT_EXCEEDS_PERIOD_BALANCE';end if;
  if paid_sum=rent_value then
   update public.aqari_notification_outbox set status='cancelled' where workspace_id=new.workspace_id and lease_id=lease_ref and period=((r->>'period')||'-01')::date and kind='rent_reminder' and status in ('queued','awaiting_configuration');
   insert into public.aqari_notification_outbox(workspace_id,lease_id,period,kind,channel,idempotency_key) values(new.workspace_id,lease_ref,((r->>'period')||'-01')::date,'payment_thanks','email','thanks:'||lease_ref::text||':'||(r->>'period')) on conflict(workspace_id,idempotency_key) do nothing;
  end if;
 end loop;
 if jsonb_array_length(coalesce(d->'collections','[]'))<>jsonb_array_length(coalesce(d->'rentLedgerV202','[]')) then raise exception 'UNLINKED_COLLECTION';end if;
 insert into public.aqari_operation_audit(workspace_id,user_id,action,revision) values(new.workspace_id,auth.uid(),'saved_and_projected',new.revision);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_validate_contract_provisions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb:=private.aqari_unwrap(new.payload);old_d jsonb:=private.aqari_unwrap(old.payload);c jsonb;previous jsonb;a jsonb;r jsonb;receipt jsonb;f text;last_month text;old_n integer;idx integer;due numeric;
begin
 for previous in select value from jsonb_array_elements(coalesce(old_d->'contractsV202','[]')) where value->>'rentalTermsVersion'='1' loop
  if not exists(select 1 from jsonb_array_elements(coalesce(d->'contractsV202','[]')) x where x->>'id'=previous->>'id') then raise exception 'لا يمكن حذف العقد المرتبط وسجله السابق.';end if;
 end loop;
 for c in select value from jsonb_array_elements(coalesce(d->'contractsV202','[]')) loop
  select x into previous from jsonb_array_elements(coalesce(old_d->'contractsV202','[]')) x where x->>'id'=c->>'id';
  if c=previous or c->>'rentalTermsVersion' is distinct from '1' then continue;end if;
  if c->>'source'<>'v267-cloud' then raise exception 'الشروط الجديدة متاحة للعقود الجديدة فقط دون تغيير أصل الاستيراد.';end if;
  if jsonb_typeof(c->'freeMonthApproved') is distinct from 'boolean' or jsonb_typeof(c->'rentAdjustments') is distinct from 'array' then raise exception 'أكمل إعداد الشهر المجاني وجدول التعديلات.';end if;
  if nullif(c->>'depositReceivedOn','') is not null then
   if c->>'depositReceivedOn' !~ '^\d{4}-\d{2}-\d{2}$' or (c->>'deposit')::numeric<=0 or (c->>'depositReceivedOn')::date>(now() at time zone 'Asia/Kuwait')::date then raise exception 'راجع مبلغ وتاريخ استلام التأمين.';end if;
  end if;
  if c->>'freeMonthApproved'='true' then
   if coalesce(c->>'freeMonthPeriod','') !~ '^\d{4}-(0[1-9]|1[0-2])$' or c->>'freeMonthPeriod'<left(c->>'start_date',7) or c->>'freeMonthPeriod'>left(c->>'end_date',7) then raise exception 'الشهر المجاني خارج مدة العقد.';end if;
   if (previous->>'freeMonthApproved' is distinct from 'true' or previous->>'freeMonthPeriod' is distinct from c->>'freeMonthPeriod') and not private.aqari_manager(new.workspace_id) then raise insufficient_privilege using message='اعتماد المدير العام مطلوب للشهر المجاني.';end if;
  elsif coalesce(c->>'freeMonthPeriod','')<>'' then raise exception 'حدد الشهر فقط عند اعتماده.';end if;
  if previous is not null then
   if previous->>'status'<>'draft' and not private.aqari_manager(new.workspace_id) then raise insufficient_privilege using message='تعديل العقد بعد المسودة يتطلب اعتماد المدير العام.';end if;
   if length(btrim(coalesce(c->>'changeReason',''))) not between 3 and 500 then raise exception 'أدخل سبب التعديل لحفظه في سجل العقد.';end if;
   foreach f in array array['tenantId','tenantProfile','tenant','property','unit','contract_no','writtenOn','contractRent','rent','discount'] loop
    if c->f is distinct from previous->f then raise exception 'هوية العقد وشروطه الأصلية ثابتة؛ استخدم تعديل الخصم المؤرخ.';end if;
   end loop;
   if c->'freeMonthApproved' is distinct from previous->'freeMonthApproved' or c->'freeMonthPeriod' is distinct from previous->'freeMonthPeriod' then
    if not private.aqari_manager(new.workspace_id) then raise insufficient_privilege using message='اعتماد المدير العام مطلوب.';end if;
    if exists(select 1 from jsonb_array_elements(coalesce(old_d->'rentLedgerV202','[]')) x where x->>'contractId'=c->>'id' and x->>'period' in (c->>'freeMonthPeriod',previous->>'freeMonthPeriod')) then raise exception 'لا يمكن تغيير شهر مجاني مرتبط بتحصيل محفوظ.';end if;
   end if;
  end if;
  old_n:=coalesce(jsonb_array_length(previous->'rentAdjustments'),0);idx:=0;last_month:='';
  if jsonb_array_length(c->'rentAdjustments')<old_n or jsonb_array_length(c->'rentAdjustments')>old_n+1 then raise exception 'التعديلات السابقة ثابتة؛ أضف تعديلاً واحداً مؤرخاً.';end if;
  for a in select value from jsonb_array_elements(c->'rentAdjustments') loop
   if coalesce(a->>'effectiveMonth','') !~ '^\d{4}-(0[1-9]|1[0-2])$' or a->>'effectiveMonth'<=last_month or a->>'effectiveMonth'<left(c->>'start_date',7) or a->>'effectiveMonth'>left(c->>'end_date',7) or length(btrim(coalesce(a->>'reason','')))<3 then raise exception 'راجع شهر التعديل وسببه.';end if;
   if jsonb_typeof(a->'discount') is distinct from 'number' or jsonb_typeof(a->'rent') is distinct from 'number' or (a->>'discount')::numeric<0 or round((a->>'discount')::numeric,3)<>(a->>'discount')::numeric or (a->>'rent')::numeric<=0 or (a->>'rent')::numeric<>(c->>'contractRent')::numeric-(a->>'discount')::numeric then raise exception 'قيمة تعديل الخصم غير صالحة.';end if;
   if idx<old_n then
    if a is distinct from previous->'rentAdjustments'->idx then raise exception 'لا يمكن استبدال تعديل سابق.';end if;
   else
    if not private.aqari_manager(new.workspace_id) then raise insufficient_privilege using message='اعتماد المدير العام مطلوب لتعديل الخصم.';end if;
    if a->>'effectiveMonth'<to_char(now() at time zone 'Asia/Kuwait','YYYY-MM') then raise exception 'لا يمكن تطبيق تعديل الخصم بأثر رجعي.';end if;
    if exists(select 1 from jsonb_array_elements(coalesce(old_d->'rentLedgerV202','[]')) x where x->>'contractId'=c->>'id' and x->>'period'>=a->>'effectiveMonth') then raise exception 'يوجد تحصيل محفوظ في فترة التعديل؛ اختر فترة لاحقة.';end if;
   end if;
   idx:=idx+1;last_month:=a->>'effectiveMonth';
  end loop;
  if c->>'status' in ('approved','signed') and previous->>'status' is distinct from c->>'status' and not private.aqari_manager(new.workspace_id) then raise insufficient_privilege using message='اعتماد المدير العام مطلوب.';end if;
  if c->>'status'='signed' and previous->>'status' is distinct from 'signed' and not exists(select 1 from public.aqari_documents where workspace_id=new.workspace_id and entity_type='lease' and entity_ref=c->>'id' and document_type='signed_contract' and status='uploaded') then raise exception 'ارفع العقد الموقّع وربطه بهذا العقد قبل اعتماد التوقيع.';end if;
 end loop;
 for r in select value from jsonb_array_elements(coalesce(d->'rentLedgerV202','[]')) loop
  if exists(select 1 from jsonb_array_elements(coalesce(old_d->'rentLedgerV202','[]')) x where x=r) then continue;end if;
  select x into c from jsonb_array_elements(coalesce(d->'contractsV202','[]')) x where x->>'id'=r->>'contractId';
  if c->>'rentalTermsVersion' is distinct from '1' then continue;end if;
  due:=private.aqari_contract_due(c,r->>'period');
  if due<=0 or (r->>'due')::numeric is distinct from due then raise exception 'المستحق لا يطابق الشهر والخصم المعتمدين، أو الشهر مجاني.';end if;
  select x into receipt from jsonb_array_elements(coalesce(d->'rentReceiptsV267','[]')) x where x->>'id'=r->>'receiptNo';
  foreach f in array array['rentalTermsVersion','depositReceivedOn','freeMonthApproved','freeMonthPeriod','rentAdjustments'] loop
   if receipt->'contract'->f is distinct from c->f then raise exception 'بيانات الوصل لا تطابق نسخة العقد المحفوظة.';end if;
  end loop;
 end loop;return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_validate_rental_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb; old_d jsonb; c jsonb; previous jsonb; p jsonb; r jsonb; receipt jsonb; f text;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 d:=private.aqari_unwrap(new.payload);old_d:=private.aqari_unwrap(old.payload);
 for c in select value from jsonb_array_elements(coalesce(d->'contractsV202','[]')) loop
  select x into previous from jsonb_array_elements(coalesce(old_d->'contractsV202','[]')) x where x->>'id'=c->>'id';
  if c=previous or c->>'source' is distinct from 'v267-cloud' then continue;end if;
  if c->>'detailsVersion' is distinct from '2' then raise exception 'CONTRACT_DETAILS_REQUIRED';end if;
  select x into p from jsonb_array_elements(coalesce(d->'tenantProfilesV267','[]')) x where x->>'id'=c->>'tenantId';
  foreach f in array array['nameAr','nameEn','nationality','civilId','passportNo','phone'] loop
   if jsonb_typeof(p->f) is distinct from 'string' or length(btrim(p->>f)) not between 1 and 300 then raise exception 'TENANT_FIELD_REQUIRED:%',f;end if;
  end loop;
  if p->>'civilId' !~ '^[0-9]{12}$' or p->>'phone' !~ '^[+]?[0-9]{8,15}$' or (p ? 'email' and p->'email' <> 'null'::jsonb and
   (jsonb_typeof(p->'email') is distinct from 'string' or length(p->>'email')>300 or
    (nullif(btrim(p->>'email'),'') is not null and btrim(p->>'email') !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'))) then raise exception 'TENANT_DETAILS_INVALID';end if;
  if (c->>'rentalTermsVersion'='1' and previous is not null and (c->'tenantProfile' is distinct from previous->'tenantProfile' or c->>'tenant' is distinct from previous->>'tenant')) or ((c->>'rentalTermsVersion' is distinct from '1' or previous is null) and (c->'tenantProfile' is distinct from p or c->>'tenant' is distinct from p->>'nameAr')) then raise exception 'TENANT_SNAPSHOT_MISMATCH';end if;
  foreach f in array array['unit','floor','contract_no','accountant','start_date','end_date','writtenOn'] loop
   if jsonb_typeof(c->f) is distinct from 'string' or length(btrim(c->>f)) not between 1 and 300 then raise exception 'CONTRACT_FIELD_REQUIRED:%',f;end if;
  end loop;
  foreach f in array array['contractRent','discount','rent','deposit','advance','cleaningFee'] loop
   if jsonb_typeof(c->f) is distinct from 'number' or (c->>f)::numeric<0 or (c->>f)::numeric<>round((c->>f)::numeric,3) then raise exception 'CONTRACT_AMOUNT_INVALID:%',f;end if;
  end loop;
  if (c->>'rent')::numeric<=0 or (c->>'rent')::numeric<>(c->>'contractRent')::numeric-(c->>'discount')::numeric then raise exception 'RENT_DISCOUNT_MISMATCH';end if;
  foreach f in array array['start_date','end_date','writtenOn'] loop
   if c->>f !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or to_char((c->>f)::date,'YYYY-MM-DD')<>c->>f then raise exception 'CONTRACT_DATE_INVALID';end if;
  end loop;
  if (c->>'end_date')::date<(c->>'start_date')::date then raise exception 'CONTRACT_DATE_ORDER';end if;
  if c->>'rentalTermsVersion' is distinct from '1' or c->>'contractReceived'='مستلم' then
  if c->>'receivedAt' is null or c->>'receivedAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[+]03:00$' or to_char((c->>'receivedAt')::timestamptz at time zone 'Asia/Kuwait','YYYY-MM-DD"T"HH24:MI:SS')||'+03:00'<>c->>'receivedAt' or (c->>'receivedAt')::timestamptz>now() or c->>'contractReceived' is distinct from 'مستلم' then raise exception 'CONTRACT_DELIVERY_INVALID';end if;
  elsif c->>'contractReceived' is distinct from 'لم يستلم' or coalesce(c->>'receivedAt','')<>'' then raise exception 'CONTRACT_DELIVERY_INVALID';end if;
  if coalesce(c->>'evictionNotice','') not in ('لم يُبلّغ','تم التبليغ','غير محدد') then raise exception 'EVICTION_STATUS_REQUIRED';end if;
  if previous->>'rentalTermsVersion'='1' and c->>'rentalTermsVersion' is distinct from '1' then raise exception 'لا يمكن إزالة ربط الشروط المعتمدة.';end if;
  if previous->>'detailsVersion'='2' then
   if previous->'contractRent' is distinct from c->'contractRent' or previous->'writtenOn' is distinct from c->'writtenOn' then raise exception 'CONTRACT_ORIGINAL_TERMS_IMMUTABLE';end if;
  elsif (c->>'writtenOn')::date<>(now() at time zone 'Asia/Kuwait')::date then raise exception 'CONTRACT_WRITING_DATE_INVALID';end if;
 end loop;
 for r in select value from jsonb_array_elements(coalesce(d->'rentLedgerV202','[]')) loop
  if exists(select 1 from jsonb_array_elements(coalesce(old_d->'rentLedgerV202','[]')) x where x=r) then continue;end if;
  select x into c from jsonb_array_elements(coalesce(d->'contractsV202','[]')) x where x->>'id'=r->>'contractId';
  if c->>'detailsVersion' is distinct from '2' then continue;end if;
  select x into receipt from jsonb_array_elements(coalesce(d->'rentReceiptsV267','[]')) x where x->>'id'=r->>'receiptNo';
  if receipt->>'detailsVersion' is distinct from '2' or receipt->>'accountant' is distinct from c->>'accountant' or r->>'accountant' is distinct from c->>'accountant' then raise exception 'RECEIPT_ACCOUNTANT_MISMATCH';end if;
  if nullif(btrim(r->>'method'),'') is null or (r->>'method'<>'نقدي' and nullif(btrim(r->>'transactionNo'),'') is null) or receipt->>'transactionNo' is distinct from r->>'transactionNo' then raise exception 'PAYMENT_TRANSACTION_REQUIRED';end if;
  foreach f in array array['tenantProfile','tenantId','floor','contractRent','discount','rent','deposit','advance','cleaningFee','writtenOn','receivedAt','contractReceived','evictionNotice','accountant'] loop
   if receipt->'contract'->f is distinct from c->f then raise exception 'RECEIPT_DETAILS_MISMATCH:%',f;end if;
  end loop;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_control_center(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;
begin
 if not private.aqari_manager(p_workspace_id) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select to_jsonb(x) into c from public.aqari_workspace_controls x where workspace_id=p_workspace_id;
 return jsonb_build_object('control',coalesce(c,jsonb_build_object('workspace_id',p_workspace_id,'settings','{"sections":{},"permissions":{},"labels":{}}'::jsonb,'revision',0)),
 'members',(select coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'is_active',m.is_active,'display_name',p.display_name) order by m.created_at),'[]') from public.aqari_memberships m left join public.aqari_profiles p on p.user_id=m.user_id where m.workspace_id=p_workspace_id));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_document_entities(p_workspace_id uuid, p_type text, p_query text DEFAULT ''::text)
 RETURNS TABLE(entity_ref text, title text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
 if not private.aqari_can(p_workspace_id,'documents','read') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if length(coalesce(p_query,''))>100 then raise exception 'INVALID_QUERY';end if;
 if p_type='property' then return query select p.external_ref,p.name from public.aqari_properties p where p.workspace_id=p_workspace_id and (p_query='' or strpos(lower(p.name),lower(p_query))>0) order by p.name,p.id limit 50;
 elsif p_type='tenant' then return query select t.external_ref,t.full_name from public.aqari_tenants t where t.workspace_id=p_workspace_id and (p_query='' or strpos(lower(t.full_name),lower(p_query))>0 or strpos(t.civil_id,p_query)>0) order by t.full_name,t.id limit 50;
 elsif p_type='lease' then return query select l.external_ref,l.contract_no||' • '||coalesce(l.snapshot->>'property','')||' • '||coalesce(l.snapshot->>'unit','') from public.aqari_leases l where l.workspace_id=p_workspace_id and (p_query='' or strpos(lower(l.contract_no||' '||coalesce(l.snapshot->>'tenant','')||' '||coalesce(l.snapshot->>'unit','')),lower(p_query))>0) order by l.contract_no,l.id limit 50;
 else raise exception 'INVALID_ENTITY_TYPE';end if;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_document_listing(p_workspace_id uuid, p_entity_type text, p_entity_ref text, p_page integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not private.aqari_can(p_workspace_id,'documents','read') or not private.aqari_document_entity(p_workspace_id,p_entity_type,p_entity_ref,'read') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_page is null or p_page<0 or p_page>10000 then raise exception 'INVALID_PAGE';end if;
 return (select coalesce(jsonb_agg(to_jsonb(rows)),'[]') from (
  select d.id,d.document_no,d.title,d.entity_type,d.entity_ref,d.status,d.created_by,d.created_at,d.uploaded_at,d.storage_path,d.mime_type,d.size_bytes,p.display_name as author_name
  from public.aqari_documents d left join public.aqari_profiles p on p.user_id=d.created_by
  where d.workspace_id=p_workspace_id and d.entity_type=p_entity_type and d.entity_ref=p_entity_ref
  order by d.created_at desc,d.id desc limit 20 offset p_page*20
 ) rows);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_finalize_document(p_document_id uuid, p_size_bytes bigint, p_mime_type text, p_checksum text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.aqari_documents%rowtype;
begin
 select * into target from public.aqari_documents where id=p_document_id for update;
 if not found or target.created_by is distinct from auth.uid() or not private.aqari_can(target.workspace_id,'documents','write') or not private.aqari_document_entity(target.workspace_id,target.entity_type,target.entity_ref,'write') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if target.status='uploaded' and target.size_bytes=p_size_bytes and target.mime_type=p_mime_type and target.checksum_sha256 is not distinct from p_checksum then return target.id;end if;
 if target.status<>'draft' then raise exception 'DOCUMENT_IMMUTABLE';end if;
 if p_size_bytes is null or p_size_bytes not between 1 and 26214400 or p_mime_type is distinct from target.mime_type or (p_checksum is not null and p_checksum !~ '^[a-f0-9]{64}$') then raise exception 'INVALID_DOCUMENT';end if;
 update public.aqari_documents set status='uploaded',size_bytes=p_size_bytes,checksum_sha256=p_checksum where id=target.id;
 return target.id;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_hr(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id; d jsonb:=p_data; e private.aqari_hr_employees; p private.aqari_hr_payroll; doc private.aqari_hr_documents;
 props uuid[]; profile jsonb; result jsonb; key text; uid uuid; ident uuid; n integer; balance numeric; period date; approval jsonb;
begin
 if not private.aqari_can(w,'employees','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d)<>'object' then raise exception 'بيانات غير صالحة.';end if;
 if p_action='list' then
  return jsonb_build_object('manager',private.aqari_manager(w),'employees',coalesce((select jsonb_agg(to_jsonb(x) order by x.profile->>'name_ar') from private.aqari_hr_employees x where x.workspace_id=w and private.aqari_hr_can(w,x.property_ids,'read')),'[]'),
   'members',case when private.aqari_manager(w) then (select jsonb_agg(jsonb_build_object('user_id',m.user_id,'name',q.display_name)) from public.aqari_memberships m left join public.aqari_profiles q on q.user_id=m.user_id where m.workspace_id=w and m.is_active) else '[]'::jsonb end,
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'name',q.name) order by q.name) from public.aqari_properties q where q.workspace_id=w and private.aqari_hr_can(w,array[q.id],'read')),'[]'));
 end if;
 if p_action in ('access','grant') then
  if not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if p_action='grant' then
   if not private.aqari_can(w,'employees','write') then raise insufficient_privilege using message='SECTION_WRITE_DENIED';end if;
   uid:=(d->>'user_id')::uuid;select array_agg(distinct x::uuid) into props from jsonb_array_elements_text(d->'property_ids') x;
   if not exists(select 1 from public.aqari_memberships where workspace_id=w and user_id=uid and is_active) or cardinality(props) is null
    or exists(select 1 from unnest(props) x where not exists(select 1 from public.aqari_properties where id=x and workspace_id=w)) then raise exception 'اختر حساباً نشطاً وعقاراً محفوظاً.';end if;
   profile:=d->'permissions';
   if jsonb_typeof(profile)<>'object' or (select count(*) from jsonb_object_keys(profile))<>5 then raise exception 'صلاحيات غير مكتملة.';end if;
   foreach key in array array['read','add','edit','approve_admin','approve_chairman'] loop
    if jsonb_typeof(profile->key) is distinct from 'boolean' then raise exception 'صلاحية غير صالحة.';end if;
   end loop;
   -- CAS also covers revocation; read=false revokes all HR access immediately.
   insert into private.aqari_hr_grants(workspace_id,user_id,property_ids,permissions) select w,uid,props,profile where coalesce((d->>'revision')::bigint,0)=0
    on conflict do nothing;
   get diagnostics n=row_count;
   if n=0 then
    update private.aqari_hr_grants set property_ids=props,permissions=profile,revision=revision+1 where workspace_id=w and user_id=uid and revision=(d->>'revision')::bigint;
    get diagnostics n=row_count;if n=0 then raise serialization_failure using message='REVISION_CONFLICT';end if;
   end if;
  end if;
  return jsonb_build_object('members',(select jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'name',q.display_name)) from public.aqari_memberships m left join public.aqari_profiles q on q.user_id=m.user_id where m.workspace_id=w and m.is_active),
   'grants',coalesce((select jsonb_agg(to_jsonb(g)) from private.aqari_hr_grants g where g.workspace_id=w),'[]'),
   'audit',coalesce((select jsonb_agg(to_jsonb(x) order by x.id desc) from (select * from private.aqari_hr_audit where workspace_id=w and entity='aqari_hr_grants' order by id desc limit 100) x),'[]'));
 end if;
 ident:=(d->>'employee_id')::uuid;
 -- Lock employee first for every mutation; serializes advance repayment and property reassignment.
 select * into e from private.aqari_hr_employees where id=ident and workspace_id=w for update;
 if p_action='save_employee' then
  select array_agg(distinct x::uuid) into props from jsonb_array_elements_text(d->'property_ids') x;
  if cardinality(props) is null or exists(select 1 from unnest(props) x where not exists(select 1 from public.aqari_properties where id=x and workspace_id=w)) then raise exception 'اختر عقاراً محفوظاً واحداً على الأقل.';end if;
  if not private.aqari_hr_can(w,props,case when e.id is null then 'add' else 'edit' end) or (e.id is not null and not private.aqari_hr_can(w,e.property_ids,'edit')) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  uid:=case when d ? 'user_id' then nullif(d->>'user_id','')::uuid else e.user_id end;
  if uid is distinct from e.user_id and not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if uid is not null and not exists(select 1 from public.aqari_memberships where workspace_id=w and user_id=uid and is_active) then raise exception 'اختر حساب دخول نشطاً في مساحة العمل.';end if;
  profile:=d->'profile';
  if jsonb_typeof(profile)<>'object' or (select count(*) from jsonb_object_keys(profile)) not between 9 and 10 or exists(select 1 from jsonb_object_keys(profile) k where k not in ('name_ar','name_en','civil_id','passport','nationality','nationality_en','phone','job_ar','job_en','work_location')) then raise exception 'أكمل بيانات الموظف.';end if;
  foreach key in array array['name_ar','name_en','civil_id','passport','nationality','phone','job_ar','job_en','work_location'] loop
   if jsonb_typeof(profile->key) is distinct from 'string' or length(btrim(profile->>key)) not between 1 and 200 or (profile->>key) ~ '[<>[:cntrl:]]' then raise exception 'أكمل جميع الحقول النصية دون رموز HTML.';end if;
  end loop;
  if profile ? 'nationality_en' and (jsonb_typeof(profile->'nationality_en')<>'string' or length(profile->>'nationality_en')>200 or (profile->>'nationality_en') ~ '[<>[:cntrl:]]') then raise exception 'راجع الجنسية بالإنجليزي.';end if;
  if coalesce(d->>'hired_on','') !~ '^\d{4}-\d{2}-\d{2}$' or (d->>'hired_on')::date<'1900-01-01'::date or d->>'status' not in ('active','leave','inactive') then raise exception 'راجع تاريخ التعيين والحالة.';end if;
  if e.id is null then
   if coalesce((d->>'revision')::bigint,0)<>0 then raise serialization_failure using message='REVISION_CONFLICT';end if;
   insert into private.aqari_hr_employees(id,workspace_id,user_id,profile,property_ids,basic,allowances,hired_on,status) values(ident,w,uid,profile,props,private.aqari_hr_money(d->'basic'),private.aqari_hr_money(d->'allowances'),(d->>'hired_on')::date,d->>'status');
  else
   if e.revision is distinct from (d->>'revision')::bigint then raise serialization_failure using message='REVISION_CONFLICT';end if;
   update private.aqari_hr_employees x set user_id=uid,profile=d->'profile',property_ids=props,basic=private.aqari_hr_money(d->'basic'),allowances=private.aqari_hr_money(d->'allowances'),hired_on=(d->>'hired_on')::date,status=d->>'status',revision=x.revision+1,updated_at=now() where x.id=e.id;
  end if;
  select * into e from private.aqari_hr_employees where id=ident;
 else
  if e.id is null or not private.aqari_hr_can(w,e.property_ids,'read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 end if;
 if p_action in ('event','prepare','save_payroll','issue','paid','reserve','finalize') and not private.aqari_hr_can(w,e.property_ids,case when p_action in ('event','prepare','reserve','finalize') then 'add' else 'edit' end) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action in ('event','edit_event') then
  if p_action='edit_event' and not private.aqari_hr_can(w,e.property_ids,'edit') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if d->>'kind' not in ('leave','advance') or length(btrim(d->>'notes')) not between 1 and 1000 then raise exception 'أدخل نوع السجل ومرجعه.';end if;
  if p_action='event' then
  insert into private.aqari_hr_events(id,workspace_id,employee_id,kind,on_date,until_date,amount,notes) values((d->>'id')::uuid,w,e.id,d->>'kind',(d->>'on_date')::date,case when d->>'kind'='leave' then (d->>'until_date')::date end,case when d->>'kind'='advance' then private.aqari_hr_money(d->'amount') end,d->>'notes');
  else
   update private.aqari_hr_events set kind=d->>'kind',on_date=(d->>'on_date')::date,until_date=case when d->>'kind'='leave' then (d->>'until_date')::date end,amount=case when d->>'kind'='advance' then private.aqari_hr_money(d->'amount') end,notes=d->>'notes',revision=revision+1 where id=(d->>'id')::uuid and employee_id=e.id and workspace_id=w and revision=(d->>'revision')::bigint;
   get diagnostics n=row_count;if n=0 then raise serialization_failure using message='REVISION_CONFLICT';end if;
   select coalesce((select sum(amount) from private.aqari_hr_events where employee_id=e.id and kind='advance'),0)-coalesce((select sum(advance_repayment-loan_payment) from private.aqari_hr_payroll where employee_id=e.id and state='paid'),0) into balance;
   if balance<0 then raise exception 'التصحيح يقلل السلف عن الأقساط المصروفة بالفعل.';end if;
  end if;
 elsif p_action='prepare' then
  period:=(d->>'month')::date;
  if period is null or period<'2000-01-01' or period>date_trunc('month',now() at time zone 'Asia/Kuwait')::date+interval '1 month' then raise exception 'اختر شهر راتب صحيحاً.';end if;
  n:=private.aqari_hr_prepare(w,period,e.id);
  if n=0 and not exists(select 1 from private.aqari_hr_payroll where employee_id=e.id and month=period) then raise exception 'راجع حالة الموظف وتاريخ تعيينه.';end if;
 elsif p_action in ('save_payroll','issue','approve_admin','approve_chairman','paid') then
  select * into p from private.aqari_hr_payroll where id=(d->>'payroll_id')::uuid and employee_id=e.id and workspace_id=w for update;
  if p.id is null then raise exception 'الراتب غير موجود.';end if;
  if p.revision is distinct from (d->>'revision')::bigint then raise serialization_failure using message='REVISION_CONFLICT';end if;
  if p_action='save_payroll' then
   if p.state<>'draft' then raise exception 'الراتب الصادر ثابت ولا يمكن تعديله.';end if;
   if d->>'method' not in ('cash','cheque','transfer') or length(coalesce(d->>'reference',''))>120 or length(coalesce(d->>'notes',''))>1000 then raise exception 'راجع طريقة الصرف والمرجع.';end if;
   update private.aqari_hr_payroll set loan_payment=case when d ? 'loan_payment' then private.aqari_hr_money(d->'loan_payment') else p.loan_payment end,reward=case when d ? 'reward' then private.aqari_hr_money(d->'reward') else p.reward end,housing=case when d ? 'housing' then private.aqari_hr_money(d->'housing') else p.housing end,indemnity=case when d ? 'indemnity' then private.aqari_hr_money(d->'indemnity') else p.indemnity end,holidays=case when d ? 'holidays' then private.aqari_hr_money(d->'holidays') else p.holidays end,late=case when d ? 'late' then private.aqari_hr_money(d->'late') else p.late end,absence=case when d ? 'absence' then private.aqari_hr_money(d->'absence') else p.absence end,slip_details=case when d ? 'slip_details' then private.aqari_hr_slip_details(d->'slip_details') else p.slip_details end,overtime=private.aqari_hr_money(d->'overtime'),deductions=private.aqari_hr_money(d->'deductions'),advance_repayment=private.aqari_hr_money(d->'advance_repayment'),method=d->>'method',reference=coalesce(d->>'reference',''),notes=coalesce(d->>'notes',''),revision=revision+1,updated_at=now() where id=p.id;
  elsif p_action='issue' then
   if p.state<>'draft' or (p.method<>'cash' and btrim(p.reference)='') then raise exception 'أكمل مرجع الشيك أو التحويل قبل الإصدار.';end if;
   if p.slip_details->>'template'='dhahawi-v1' and (btrim(coalesce(p.slip_details->>'payer_ar',''))='' or btrim(coalesce(p.slip_details->>'payer_en',''))='') then raise exception 'أكمل اسم مسؤول الصرف بالعربي والإنجليزي في السند.';end if;
   update private.aqari_hr_payroll set issued_at=now(),voucher_no=(case when p.slip_details->>'template'='dhahawi-v1' then 'DT-' else 'AQ-' end)||to_char(now() at time zone 'Asia/Kuwait','YYYYMMDD')||'-'||lpad(nextval('private.aqari_hr_voucher_seq')::text,6,'0'),state='issued',revision=revision+1,updated_at=now() where id=p.id;
  elsif p_action in ('approve_admin','approve_chairman') then
   if not private.aqari_hr_can(w,e.property_ids,p_action) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
   if p.state<>'issued' then raise exception 'يلزم إصدار الراتب أولاً.';end if;
   if (p_action='approve_admin' and p.admin_approval is not null) or (p_action='approve_chairman' and p.chairman_approval is not null) then raise exception 'الاعتماد محفوظ بالفعل.';end if;
   if (p_action='approve_admin' and p.chairman_approval->>'user_id'=auth.uid()::text) or (p_action='approve_chairman' and p.admin_approval->>'user_id'=auth.uid()::text) then raise exception 'يلزم حساب مختلف للاعتماد الثاني.';end if;
   select jsonb_build_object('user_id',auth.uid(),'name',coalesce(display_name,auth.uid()::text),'at',now()) into approval from public.aqari_profiles where user_id=auth.uid();
   update private.aqari_hr_payroll set admin_approval=case when p_action='approve_admin' then approval else admin_approval end,chairman_approval=case when p_action='approve_chairman' then approval else chairman_approval end,revision=revision+1,updated_at=now() where id=p.id;
  else
   if p.state<>'issued' or p.admin_approval is null or p.chairman_approval is null or not exists(select 1 from private.aqari_hr_documents where payroll_id=p.id and status='ready' and attestations='{"signature":true,"fingerprint":true,"stamp":true}'::jsonb) then raise exception 'يلزم الاعتمادان والنسخة الموقعة مع البصمة والختم قبل إثبات الصرف.';end if;
   select coalesce((select sum(amount) from private.aqari_hr_events where employee_id=e.id and kind='advance'),0)-coalesce((select sum(advance_repayment-loan_payment) from private.aqari_hr_payroll where employee_id=e.id and state='paid'),0) into balance;
   if p.advance_repayment>balance then raise exception 'قسط السلفة يتجاوز الرصيد المتبقي.';end if;
   update private.aqari_hr_payroll set state='paid',paid_at=now(),revision=revision+1,updated_at=now() where id=p.id;
  end if;
 elsif p_action='reserve' then
  if d->>'kind' not in ('document','employment_contract','signed_salary') or length(coalesce(d->>'filename','')) not between 1 and 200 or (d->>'filename')~'[/\\[:cntrl:]]' then raise exception 'اسم أو نوع المستند غير صالح.';end if;
  if d->>'kind'='signed_salary' then
   select * into p from private.aqari_hr_payroll where id=(d->>'payroll_id')::uuid and employee_id=e.id and workspace_id=w;
   if p.id is null or p.state='draft' then raise exception 'أصدر الراتب قبل رفع نسخته الموقعة.';end if;
  end if;
  uid:=(d->>'id')::uuid;
  insert into private.aqari_hr_documents(id,workspace_id,employee_id,payroll_id,kind,filename,mime_type,size_bytes,storage_path,created_by)
  values(uid,w,e.id,p.id,d->>'kind',d->>'filename',d->>'mime_type',(d->>'size_bytes')::bigint,w::text||'/'||e.id::text||'/'||case when p.id is not null then to_char(p.month,'YYYY/MM')||'/' else 'documents/' end||uid::text,auth.uid()) on conflict(id) do nothing;
  select * into doc from private.aqari_hr_documents where id=uid and employee_id=e.id and workspace_id=w and created_by=auth.uid();
  if doc.id is null or doc.filename<>d->>'filename' or doc.mime_type<>d->>'mime_type' or doc.size_bytes<>(d->>'size_bytes')::bigint or doc.payroll_id is distinct from p.id or doc.kind<>d->>'kind' then raise exception 'تعارض مرجع الرفع.';end if;
  return to_jsonb(doc);
 elsif p_action='finalize' then
  select * into doc from private.aqari_hr_documents where id=(d->>'id')::uuid and employee_id=e.id and workspace_id=w for update;
  if doc.id is null then raise exception 'المستند غير موجود.';end if;
  if doc.status='ready' then return to_jsonb(doc);end if;
  if doc.kind='signed_salary' and d->'attestations' is distinct from '{"signature":true,"fingerprint":true,"stamp":true}'::jsonb then raise exception 'أكد وجود التوقيع والبصمة وختم الإدارة في النسخة الفعلية.';end if;
  if not exists(select 1 from storage.objects where bucket_id='aqari-hr-private' and name=doc.storage_path and (metadata->>'size')::bigint=doc.size_bytes and metadata->>'mimetype'=doc.mime_type) then raise exception 'STORED_FILE_NOT_CONFIRMED';end if;
  update private.aqari_hr_documents set status='ready',uploaded_at=now(),attestations=case when kind='signed_salary' then d->'attestations' else '{}' end where id=doc.id returning * into doc;
  return to_jsonb(doc);
 elsif p_action not in ('get','save_employee') then raise exception 'عملية غير معروفة.';
 end if;
 select coalesce((select sum(amount) from private.aqari_hr_events where employee_id=e.id and kind='advance'),0)-coalesce((select sum(advance_repayment-loan_payment) from private.aqari_hr_payroll where employee_id=e.id and state='paid'),0) into balance;
 return jsonb_build_object('employee',to_jsonb(e),'advance_balance',balance,
  'permissions',jsonb_build_object('read',true,'add',private.aqari_hr_can(w,e.property_ids,'add'),'edit',private.aqari_hr_can(w,e.property_ids,'edit'),'approve_admin',private.aqari_hr_can(w,e.property_ids,'approve_admin'),'approve_chairman',private.aqari_hr_can(w,e.property_ids,'approve_chairman')),
  'payroll',coalesce((select jsonb_agg(to_jsonb(x) order by x.month desc) from private.aqari_hr_payroll x where employee_id=e.id),'[]'),
  'events',coalesce((select jsonb_agg(to_jsonb(x) order by x.on_date desc) from private.aqari_hr_events x where employee_id=e.id),'[]'),
  'documents',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from private.aqari_hr_documents x where employee_id=e.id),'[]'),
  'audit',coalesce((select jsonb_agg(to_jsonb(x) order by x.id desc) from (select * from private.aqari_hr_audit where workspace_id=w and employee_id=e.id order by id desc limit 100) x),'[]'));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_link_property_statement(p_workspace_id uuid, p_property_id uuid, p_period date, p_source_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare st public.aqari_property_statements%rowtype; saved public.aqari_app_state%rowtype; d jsonb; r jsonb; prof jsonb; con jsonb; prov jsonb;
 t_id uuid;l_id uuid;u_id uuid;profile_ref text;contract_ref text;identity_key text;raw_phone text;valid_phone text;valid_civil text;display_name text;start_on date;end_on date;linked integer:=0;new_profiles integer:=0;new_leases integer:=0;
begin
 if auth.uid() is null or not private.aqari_manager(p_workspace_id) or not private.aqari_can(p_workspace_id,'tenants','write') or not private.aqari_can(p_workspace_id,'contracts','write') or not private.aqari_can(p_workspace_id,'properties','write') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text,0));
 select * into strict st from public.aqari_property_statements where workspace_id=p_workspace_id and property_id=p_property_id and period=p_period;
 if st.source_sha256 is distinct from p_source_sha256 or st.content->>'property_key'<>'shaikhah-tower' then raise exception 'SOURCE_MISMATCH';end if;
 select * into strict saved from public.aqari_app_state where workspace_id=p_workspace_id for update;
 d:=private.aqari_unwrap(saved.payload);
 if not exists(select 1 from jsonb_array_elements(coalesce(d->'properties','[]')) x where x->>0=st.content->>'property_name') then
  d:=jsonb_set(d,'{properties}',coalesce(d->'properties','[]')||jsonb_build_array(jsonb_build_array(st.content->>'property_name','غير مدون',jsonb_array_length(st.content->'rows'),st.content#>'{summary,printed_totals,rent_kd}')));
 end if;
 for r in select value from jsonb_array_elements(st.content->'rows') loop
  if exists(select 1 from public.aqari_statement_links where workspace_id=p_workspace_id and property_id=p_property_id and period=p_period and unit_no=r->>'unit') then linked:=linked+1;continue;end if;
  select id into strict u_id from public.aqari_units where workspace_id=p_workspace_id and property_id=p_property_id and unit_no=r->>'unit';
  raw_phone:=nullif(r->>'phone_raw',''); valid_phone:=case when raw_phone ~ '^[+]?[0-9]{8,15}$' then raw_phone else null end;
  valid_civil:=case when r->>'civil_id_raw' ~ '^[0-9]{12}$' then r->>'civil_id_raw' else null end;
  identity_key:=md5(coalesce(r->>'civil_id_raw','')||':'||coalesce(raw_phone,'')||':'||coalesce(r->>'name_en_raw',''));
  profile_ref:='source:'||p_property_id::text||':tenant:'||identity_key;
  t_id:=md5(p_workspace_id::text||':tenant:'||profile_ref)::uuid;
  display_name:=nullif(r->>'name_en_raw','');
  prov:=jsonb_build_object('property_id',p_property_id,'period',p_period,'source_sha256',st.source_sha256,'contact_page',r->'contact_source_page','financial_page',r->'financial_source_page','linked_by',auth.uid());
  if not exists(select 1 from public.aqari_tenants where workspace_id=p_workspace_id and id=t_id) then
   if exists(select 1 from public.aqari_tenants where workspace_id=p_workspace_id and ((valid_civil is not null and civil_id=valid_civil) or (valid_phone is not null and phone=valid_phone))) then raise exception 'TENANT_IDENTITY_REVIEW_REQUIRED';end if;
   prof:=jsonb_build_object('id',profile_ref,'nameAr','','nameEn',coalesce(display_name,''),'civilId',coalesce(valid_civil,''),'phone',coalesce(valid_phone,''),'email','','nationality',coalesce(r->>'nationality_raw',''),'address','','attachments','[]'::jsonb,'source','statement-import','importStatus','source_saved','sourceValues',r,'sourceReference',prov);
   insert into public.aqari_tenants(id,workspace_id,external_ref,full_name,civil_id,phone,email,profile,import_source) values(t_id,p_workspace_id,profile_ref,display_name,valid_civil,valid_phone,null,prof,prov);
   d:=jsonb_set(d,'{tenantProfilesV267}',coalesce(d->'tenantProfilesV267','[]')||jsonb_build_array(prof));
   d:=jsonb_set(d,'{tenants}',coalesce(d->'tenants','[]')||jsonb_build_array(jsonb_build_array(coalesce(display_name,''),st.content->>'property_name',raw_phone,'ملف مصدر محفوظ',profile_ref)));
   new_profiles:=new_profiles+1;
  else select profile into prof from public.aqari_tenants where workspace_id=p_workspace_id and id=t_id;end if;
  contract_ref:='source:'||p_property_id::text||':lease:'||(r->>'contract_no_raw');
  l_id:=md5(p_workspace_id::text||':lease:'||contract_ref)::uuid;
  start_on:=private.aqari_source_date(r->>'contract_start_raw');end_on:=private.aqari_source_date(r->>'contract_end_raw');
  if (r->'pending') ? 'contract_dates' or end_on<start_on then start_on:=null;end_on:=null;end if;
  con:=jsonb_build_object('id',contract_ref,'source','statement-import','contract_no',r->>'contract_no_raw','tenantId',profile_ref,'tenant',coalesce(display_name,''),'tenantProfile',prof,'property',st.content->>'property_name','unit',r->>'unit','rent',r->'contract_rent_kd','currentRent',r->'current_rent_kd','deposit',null,'status','draft','start_date',start_on,'end_date',end_on,'clauses','[]'::jsonb,'sourceReference',prov,'sourceValues',r,'pending',r->'pending','importStatus','source_saved');
  insert into public.aqari_leases(id,workspace_id,external_ref,tenant_id,unit_id,contract_no,start_date,end_date,monthly_rent,deposit,status,snapshot,import_source) values(l_id,p_workspace_id,contract_ref,t_id,u_id,r->>'contract_no_raw',start_on,end_on,(r->>'contract_rent_kd')::numeric,null,'draft',con,prov);
  d:=jsonb_set(d,'{contractsV202}',coalesce(d->'contractsV202','[]')||jsonb_build_array(con));
  d:=jsonb_set(d,'{leases}',coalesce(d->'leases','[]')||jsonb_build_array(jsonb_build_array(coalesce(display_name,''),r->>'unit',r->'contract_rent_kd',end_on,contract_ref)));
  d:=jsonb_set(d,'{tenantDirectoryV202}',coalesce(d->'tenantDirectoryV202','[]')||jsonb_build_array(jsonb_build_object('property',st.content->>'property_name','unit',r->>'unit','tenant',coalesce(display_name,''),'contractNo',r->>'contract_no_raw','phone',valid_phone,'civilId',valid_civil,'nationality',r->>'nationality_raw','email','','source','statement-import','verified',false,'tenantProfileId',profile_ref)));
  insert into public.aqari_statement_links(workspace_id,property_id,period,unit_no,tenant_id,lease_id,source_sha256,linked_by) values(p_workspace_id,p_property_id,p_period,r->>'unit',t_id,l_id,st.source_sha256,auth.uid());
  linked:=linked+1;new_leases:=new_leases+1;
 end loop;
 -- The legacy tenant table columns are name / units / rent / status / profile id.
 d:=jsonb_set(d,'{tenants}',
  coalesce((select jsonb_agg(x) from jsonb_array_elements(coalesce(d->'tenants','[]')) x where not exists(select 1 from public.aqari_tenants t where t.workspace_id=p_workspace_id and t.external_ref=x->>4 and t.import_source->>'property_id'=p_property_id::text)),'[]'::jsonb)
  ||coalesce((select jsonb_agg(row_value) from (select jsonb_build_array(coalesce(t.full_name,''),string_agg(lk.unit_no,' / ' order by lk.unit_no),sum((sr->>'current_rent_kd')::numeric),'ملف مصدر محفوظ',t.external_ref) row_value from public.aqari_statement_links lk join public.aqari_tenants t on t.workspace_id=lk.workspace_id and t.id=lk.tenant_id join lateral jsonb_array_elements(st.content->'rows') sr on sr->>'unit'=lk.unit_no where lk.workspace_id=p_workspace_id and lk.property_id=p_property_id and lk.period=p_period group by t.id,t.full_name,t.external_ref order by min(lk.unit_no)) rows_for_tenants),'[]'::jsonb));
 if new_profiles>0 or new_leases>0 or d is distinct from private.aqari_unwrap(saved.payload) then
  update public.aqari_app_state set payload=case when saved.payload->>'format'='aqari-cloud-state-v1' then jsonb_set(saved.payload,'{snapshot,values,aqari_v30}',d) when saved.payload->>'schema'='aqari-local-snapshot-v1' then jsonb_set(saved.payload,'{values,aqari_v30}',d) else d end,revision=saved.revision+1,updated_by=auth.uid(),updated_at=now() where workspace_id=p_workspace_id;
  insert into public.aqari_operation_audit(workspace_id,user_id,action,revision) values(p_workspace_id,auth.uid(),'source_statement_linked:'||p_property_id::text||':'||p_period::text,saved.revision+1);
 end if;
 return jsonb_build_object('linked_rows',linked,'new_tenants',new_profiles,'new_leases',new_leases,'posted_payments',0);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_notices(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n private.aqari_property_notices%rowtype; previous jsonb; result jsonb; notice_id uuid;
 expected integer; who text; recipient public.aqari_portal_accounts%rowtype; at_time timestamptz;
 expiration timestamptz; allowed_keys text[]; why text:='';prop uuid;
begin
 if auth.uid() is null or p_workspace_id is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action is null or p_action not in ('list','save','publish','archive','history','feed','ack') then raise exception 'عملية التعاميم غير صالحة.';end if;
 if p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'بيانات التعميم غير صالحة.';end if;
 allowed_keys:=case when p_action='save' then array['id','revision','property_id','kind','title','body','expires_at']
  when p_action='archive' then array['id','revision','reason'] when p_action in ('publish','ack') then array['id','revision']
  when p_action='history' then array['id'] else array[]::text[] end;
 if exists(select 1 from jsonb_object_keys(p_data) k where not k=any(allowed_keys)) then raise exception 'حقول التعميم غير مسموحة.';end if;

 if p_action in ('feed','ack') then
  select * into recipient from public.aqari_portal_accounts a where a.user_id=auth.uid() and a.workspace_id=p_workspace_id and a.is_active;
  if not found or not private.aqari_owns_tenant(p_workspace_id,recipient.tenant_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if p_action='feed' then
   return coalesce((select jsonb_agg(q.item order by q.published_at desc,q.id) from (
    select x.id,x.published_at,jsonb_build_object('id',x.id,'property_id',x.property_id,'property_name',p.name,
     'kind',x.kind,'title',x.title,'body',x.body,'status',x.status,'revision',x.revision,
     'published_at',x.published_at,'expires_at',x.expires_at,'acknowledged_at',a.acknowledged_at) item
    from private.aqari_property_notices x join public.aqari_properties p on p.workspace_id=x.workspace_id and p.id=x.property_id
    left join private.aqari_property_notice_acknowledgements a on a.notice_id=x.id and a.notice_revision=x.revision and a.user_id=auth.uid()
    where x.workspace_id=p_workspace_id and x.status='published' and x.published_at<=now()
     and (x.expires_at is null or x.expires_at>now()) and private.aqari_can_read_property_notice(x.workspace_id,x.property_id)
    order by x.published_at desc,x.id limit 50
   ) q),'[]');
  end if;
  notice_id:=nullif(p_data->>'id','')::uuid;expected:=nullif(p_data->>'revision','')::integer;
  select * into n from private.aqari_property_notices x where x.workspace_id=p_workspace_id and x.id=notice_id for share;
  if not found or n.status<>'published' or n.published_at>now() or (n.expires_at is not null and n.expires_at<=now())
    or not private.aqari_can_read_property_notice(n.workspace_id,n.property_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if expected is distinct from n.revision then raise serialization_failure using message='REVISION_CONFLICT';end if;
  select full_name into who from public.aqari_tenants where id=recipient.tenant_id and workspace_id=p_workspace_id;
  insert into private.aqari_property_notice_acknowledgements(notice_id,notice_revision,user_id,tenant_id,user_name)
   values(n.id,n.revision,auth.uid(),recipient.tenant_id,who) on conflict on constraint aqari_property_notice_acknowledgements_pkey do nothing;
  select acknowledged_at into at_time from private.aqari_property_notice_acknowledgements a where a.notice_id=n.id and a.notice_revision=n.revision and a.user_id=auth.uid();
  return jsonb_build_object('acknowledged_at',at_time);
 end if;

 if not private.aqari_manager(p_workspace_id) or not private.aqari_can(p_workspace_id,'notifications',case when p_action in ('list','history') then 'read' else 'write' end)
 then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='list' then
  return jsonb_build_object('manager',true,
   'properties',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name),'[]') from public.aqari_properties p where p.workspace_id=p_workspace_id),
   'notices',(select coalesce(jsonb_agg(q.item order by q.updated_at desc,q.id),'[]') from (
    select x.id,x.updated_at,to_jsonb(x)||jsonb_build_object('ack_count',(select count(*) from private.aqari_property_notice_acknowledgements a where a.notice_id=x.id)) item
    from private.aqari_property_notices x where x.workspace_id=p_workspace_id order by x.updated_at desc,x.id limit 100
   ) q));
 end if;
 notice_id:=nullif(p_data->>'id','')::uuid;
 if notice_id is null then raise exception 'رقم التعميم مطلوب.';end if;
 select * into n from private.aqari_property_notices x where x.workspace_id=p_workspace_id and x.id=notice_id for update;
 if p_action='history' then
  if n.id is null then raise exception 'التعميم غير موجود.';end if;
  return jsonb_build_object('versions',(select coalesce(jsonb_agg(to_jsonb(v) order by v.revision desc),'[]') from private.aqari_property_notice_versions v where v.notice_id=n.id),
   'acknowledgements',(select coalesce(jsonb_agg(jsonb_build_object('notice_revision',a.notice_revision,'user_name',a.user_name,'acknowledged_at',a.acknowledged_at) order by a.acknowledged_at desc),'[]') from private.aqari_property_notice_acknowledgements a where a.notice_id=n.id));
 end if;
 expected:=nullif(p_data->>'revision','')::integer;
 if expected is distinct from coalesce(n.revision,0) then raise serialization_failure using message='REVISION_CONFLICT';end if;
 previous:=case when n.id is null then null else to_jsonb(n) end;
 select display_name into who from public.aqari_profiles where user_id=auth.uid();who:=coalesce(nullif(who,''),auth.uid()::text);
 if p_action='save' then
  if n.id is not null and n.status<>'draft' then raise exception 'لا يمكن تعديل النسخة المنشورة؛ أنشئ مسودة جديدة واحفظ الأصل.';end if;
  if jsonb_typeof(p_data->'title') is distinct from 'string' or jsonb_typeof(p_data->'body') is distinct from 'string'
    or length(btrim(p_data->>'title')) not between 1 and 200 or length(btrim(p_data->>'body')) not between 1 and 10000
    or coalesce(p_data->>'kind','') not in ('notice','guidance','circular') then raise exception 'أكمل عنوان التعميم ونصه ونوعه.';end if;
  prop:=nullif(p_data->>'property_id','')::uuid;
  if not exists(select 1 from public.aqari_properties where id=prop and workspace_id=p_workspace_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  expiration:=nullif(p_data->>'expires_at','')::timestamptz;
  if n.id is null then
   insert into private.aqari_property_notices(id,workspace_id,property_id,kind,title,body,expires_at,created_by)
   values(notice_id,p_workspace_id,prop,p_data->>'kind',btrim(p_data->>'title'),btrim(p_data->>'body'),expiration,auth.uid()) returning * into n;
  else
   update private.aqari_property_notices set property_id=prop,kind=p_data->>'kind',title=btrim(p_data->>'title'),body=btrim(p_data->>'body'),expires_at=expiration,revision=revision+1,updated_at=now() where id=n.id returning * into n;
  end if;
 elsif p_action='publish' then
  if n.id is null or n.status<>'draft' then raise exception 'النشر متاح للمسودة المحفوظة فقط.';end if;
  if n.expires_at is not null and n.expires_at<=now() then raise exception 'راجع موعد انتهاء عرض التعميم قبل نشره.';end if;
  update private.aqari_property_notices set status='published',published_at=now(),revision=revision+1,updated_at=now() where id=n.id returning * into n;
 else
  if n.id is null or n.status='archived' then raise exception 'التعميم غير موجود أو مؤرشف.';end if;
  why:=btrim(coalesce(p_data->>'reason',''));
  if length(why) not between 3 and 500 then raise exception 'سبب الأرشفة مطلوب لحفظ السجل.';end if;
  update private.aqari_property_notices set status='archived',revision=revision+1,updated_at=now() where id=n.id returning * into n;
 end if;
 insert into private.aqari_property_notice_versions(notice_id,revision,action,actor_id,actor_name,reason,before_snapshot,after_snapshot)
 values(n.id,n.revision,p_action,auth.uid(),who,why,previous,to_jsonb(n));
 return to_jsonb(n);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_read_state_v267(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_data public.aqari_app_state%rowtype;d jsonb;filtered jsonb;source_properties jsonb;
begin
 if not private.aqari_staff(p_workspace_id) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select * into row_data from public.aqari_app_state where workspace_id=p_workspace_id;
 if not found then return null;end if;
 d:=private.aqari_unwrap(row_data.payload);
 -- Expose independently imported properties only to the manager with property-read access.
 -- Existing property rows and every other state key are preserved.
 if private.aqari_manager(p_workspace_id) and private.aqari_can(p_workspace_id,'properties','read') then
  select coalesce(jsonb_agg(jsonb_build_array(p.name,'غير مدون',(select count(*) from public.aqari_units u where u.workspace_id=p.workspace_id and u.property_id=p.id),(select sum((r->>'current_rent_kd')::numeric) from jsonb_array_elements(s.content->'rows') r))),'[]') into source_properties
  from public.aqari_properties p join lateral(select st.content from public.aqari_property_statements st where st.workspace_id=p.workspace_id and st.property_id=p.id order by st.period desc limit 1)s on true
  where p.workspace_id=p_workspace_id and not exists(select 1 from jsonb_array_elements(coalesce(d->'properties','[]')) r where r->>0=p.name);
  d:=jsonb_set(d,'{properties}',coalesce(d->'properties','[]')||source_properties);
 end if;
 select coalesce(jsonb_object_agg(key,value),'{}') into filtered from jsonb_each(d) where private.aqari_can(p_workspace_id,private.aqari_state_section(key),'read');
 return jsonb_build_object('workspace_id',row_data.workspace_id,'payload',filtered,'revision',row_data.revision,'updated_by',row_data.updated_by,'updated_at',row_data.updated_at);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_reserve_document(p_workspace_id uuid, p_document_type text, p_entity_type text, p_entity_ref text, p_title text, p_original_filename text, p_mime_type text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(document_id uuid, document_no text, storage_bucket text, storage_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id uuid:=gen_random_uuid();new_no text;new_path text;ext text;entity text:=p_entity_type;
begin
 if not private.aqari_can(p_workspace_id,'documents','write') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 -- Compatibility for the earlier tenant attachment caller; still requires an existing saved tenant.
 if entity='other' and p_document_type='tenant_attachment' then entity:='tenant';end if;
 if not private.aqari_document_entity(p_workspace_id,entity,p_entity_ref,'write') then raise exception 'DOCUMENT_ENTITY_NOT_FOUND' using errcode='42501';end if;
 if p_mime_type is null or p_mime_type not in ('application/pdf','image/jpeg','image/png','image/webp','image/heic','image/heif','application/vnd.openxmlformats-officedocument.wordprocessingml.document')
  or p_title is null or length(btrim(p_title)) not between 1 and 180 or p_original_filename is null or length(p_original_filename) not between 1 and 250
  or p_document_type not in ('tenant_attachment','signed_contract','property_document','mobile_scan')
  or (p_document_type='tenant_attachment' and entity<>'tenant') or (p_document_type='signed_contract' and entity<>'lease')
  or p_metadata is null or jsonb_typeof(p_metadata)<>'object' or octet_length(p_metadata::text)>4096 then raise exception 'INVALID_DOCUMENT';end if;
 ext:=case p_mime_type when 'application/pdf' then 'pdf' when 'image/jpeg' then 'jpg' when 'image/png' then 'png' when 'image/webp' then 'webp' when 'image/heic' then 'heic' when 'image/heif' then 'heif' else 'docx' end;
 new_no:='DOC-'||new_id::text;new_path:=p_workspace_id::text||'/'||new_id::text||'.'||ext;
 insert into public.aqari_documents(id,workspace_id,document_no,document_type,entity_type,entity_ref,title,original_filename,mime_type,metadata,storage_path,created_by)
 values(new_id,p_workspace_id,new_no,p_document_type,entity,p_entity_ref,btrim(p_title),p_original_filename,p_mime_type,p_metadata,new_path,auth.uid());
 return query select new_id,new_no,'aqari-documents'::text,new_path;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_save_controls(p_workspace_id uuid, p_settings jsonb, p_expected_revision bigint, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row public.aqari_workspace_controls%rowtype;item record;subject record;section record;action record;lang record;label record;new_rev bigint;
begin
 if not private.aqari_manager(p_workspace_id) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_reason is null or length(btrim(p_reason)) not between 3 and 500 or p_settings is null or jsonb_typeof(p_settings)<>'object' or octet_length(p_settings::text)>65536 then raise exception 'INVALID_CONTROLS';end if;
 if not(p_settings ?& array['sections','permissions','labels']) then raise exception 'INVALID_CONTROLS';end if;
 for item in select * from jsonb_each(p_settings) loop if item.key not in ('sections','permissions','labels') or jsonb_typeof(item.value)<>'object' then raise exception 'INVALID_CONTROLS';end if;end loop;
 for item in select * from jsonb_each(p_settings->'sections') loop
  if not(item.key=any(private.aqari_section_keys())) or jsonb_typeof(item.value)<>'boolean' then raise exception 'INVALID_SECTION';end if;
 end loop;
 for subject in select * from jsonb_each(p_settings->'permissions') loop
  if subject.key not in ('role:property_manager','role:accountant','role:viewer') and not exists(select 1 from public.aqari_memberships where workspace_id=p_workspace_id and 'user:'||user_id::text=subject.key and role<>'general_manager' and is_active) then raise exception 'INVALID_SUBJECT';end if;
  if jsonb_typeof(subject.value)<>'object' then raise exception 'INVALID_PERMISSIONS';end if;
  for section in select * from jsonb_each(subject.value) loop
   if not(section.key=any(private.aqari_section_keys())) or jsonb_typeof(section.value)<>'object' then raise exception 'INVALID_PERMISSIONS';end if;
   for action in select * from jsonb_each(section.value) loop
    if action.key not in ('read','write') or jsonb_typeof(action.value)<>'boolean' then raise exception 'INVALID_PERMISSIONS';end if;
   end loop;
   if section.value->>'write'='true' and section.value->>'read'='false' then raise exception 'WRITE_REQUIRES_READ';end if;
  end loop;
 end loop;
 for lang in select * from jsonb_each(p_settings->'labels') loop
  if lang.key not in ('ar','en','hi','ur','ml') or jsonb_typeof(lang.value)<>'object' then raise exception 'INVALID_LANGUAGE';end if;
  for label in select * from jsonb_each(lang.value) loop
   if not(label.key=any(private.aqari_section_keys()||array['more','control_center','scan_document'])) or jsonb_typeof(label.value)<>'string' or length(btrim(label.value#>>'{}')) not between 1 and 80 or (label.value#>>'{}') ~ '[<>[:cntrl:]]' then raise exception 'INVALID_LABEL';end if;
  end loop;
 end loop;
 -- Lock workspace even before the first settings row: concurrent initial saves cannot overwrite.
 perform 1 from public.aqari_workspaces where id=p_workspace_id for update;
 select * into old_row from public.aqari_workspace_controls where workspace_id=p_workspace_id;
 if coalesce(old_row.revision,0) is distinct from p_expected_revision then raise exception 'REVISION_CONFLICT' using errcode='40001';end if;
 new_rev:=coalesce(old_row.revision,0)+1;
 insert into public.aqari_workspace_controls(workspace_id,settings,revision,updated_by) values(p_workspace_id,p_settings,new_rev,auth.uid())
 on conflict(workspace_id) do update set settings=excluded.settings,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=now();
 insert into public.aqari_control_audit(workspace_id,actor_id,action,entity_ref,reason,before_value,after_value) values(p_workspace_id,auth.uid(),'controls.update',p_workspace_id::text,btrim(p_reason),old_row.settings,p_settings);
 return new_rev;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_save_state_v267(p_workspace_id uuid, p_payload jsonb, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row public.aqari_app_state%rowtype;old_data jsonb;incoming jsonb;k text;merged jsonb;r text;
begin
 select role::text into r from public.aqari_memberships where workspace_id=p_workspace_id and user_id=auth.uid() and is_active;
 if r is null or r='viewer' then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select * into current_row from public.aqari_app_state where workspace_id=p_workspace_id for update;
 if not found or current_row.revision is distinct from p_expected_revision then raise exception 'REVISION_CONFLICT' using errcode='40001';end if;
 incoming:=private.aqari_unwrap(p_payload);old_data:=private.aqari_unwrap(current_row.payload);merged:=old_data;
 if incoming is null or jsonb_typeof(incoming)<>'object' then raise exception 'INVALID_STATE';end if;
 for k in select jsonb_object_keys(incoming) loop
  if k='audit' and r<>'general_manager' then continue;end if;
  if incoming->k is distinct from old_data->k then
   if not private.aqari_can(p_workspace_id,private.aqari_state_section(k),'write') then raise exception 'SECTION_WRITE_DENIED:%',k using errcode='42501';end if;
   merged:=jsonb_set(merged,array[k],incoming->k,true);
  end if;
 end loop;
 -- Absent keys are preserved, never treated as deletion of hidden data.
 update public.aqari_app_state set payload=merged where workspace_id=p_workspace_id;
 return public.aqari_read_state_v267(p_workspace_id);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_startup_snapshot_v266(p_workspace_id uuid DEFAULT NULL::uuid, p_expected_role text DEFAULT NULL::text, p_include_payload boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_member record;
  v_workspace record;
  v_profile record;
  v_app jsonb := null;
begin
  if v_uid is null then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  select m.workspace_id, m.user_id, m.role, m.is_active, m.created_at
    into v_member from public.aqari_memberships m
    where m.user_id = v_uid and m.is_active is true
      and (p_workspace_id is null or m.workspace_id = p_workspace_id)
      and (p_expected_role is null or m.role::text = p_expected_role)
    order by m.created_at, m.workspace_id limit 1;
  if not found then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  select w.id, w.name, w.slug, w.created_at into v_workspace
    from public.aqari_workspaces w where w.id = v_member.workspace_id;
  if not found then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  select p.user_id, p.display_name, p.created_at, p.updated_at into v_profile
    from public.aqari_profiles p where p.user_id = v_uid;
  if not found then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  if p_include_payload then
    v_app := public.aqari_read_state_v267(v_member.workspace_id);
  end if;
  return jsonb_build_object('user_id',v_uid,'membership',to_jsonb(v_member),
    'workspace',to_jsonb(v_workspace),'profile',to_jsonb(v_profile),'app_state',v_app);
end;
$function$

CREATE OR REPLACE FUNCTION public.aqari_tenant_portal_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare a public.aqari_portal_accounts%rowtype;
begin
 select * into a from public.aqari_portal_accounts where user_id=auth.uid() and is_active;
 if not found or not private.aqari_owns_tenant(a.workspace_id,a.tenant_id) then raise exception 'TENANT_ACCESS_DENIED' using errcode='42501';end if;
 return jsonb_build_object('account',to_jsonb(a),'tenant',(select to_jsonb(t) from public.aqari_tenants t where t.id=a.tenant_id),'leases',(select coalesce(jsonb_agg(to_jsonb(l)),'[]') from public.aqari_leases l where l.tenant_id=a.tenant_id),'payments',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.aqari_rent_payments p join public.aqari_leases l on l.id=p.lease_id where l.tenant_id=a.tenant_id),'maintenance',(select coalesce(jsonb_agg(to_jsonb(m) order by m.created_at desc),'[]') from public.aqari_maintenance_requests m where m.tenant_id=a.tenant_id));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_workspace_access(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cfg jsonb;access jsonb:='{}';s text;r text;
begin
 select role::text into r from public.aqari_memberships where workspace_id=p_workspace_id and user_id=auth.uid() and is_active;
 if r is null then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select settings into cfg from public.aqari_workspace_controls where workspace_id=p_workspace_id;
 foreach s in array private.aqari_section_keys() loop
  access:=access||jsonb_build_object(s,jsonb_build_object('read',private.aqari_can(p_workspace_id,s,'read'),'write',private.aqari_can(p_workspace_id,s,'write')));
 end loop;
 return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'role',r,'sections',coalesce(cfg->'sections','{}'),'permissions',access,'labels',coalesce(cfg->'labels','{}'));
end $function$
